#define FILE_DELETE_ROW         3U      /* the File screen's Delete row (EVENT_FILE_DELETE) */

/* -------------------------------------------------------------------------- */
/* State                                                                       */
/* -------------------------------------------------------------------------- */
typedef enum { BTN_PA8 = 0, BTN_PB0, BTN_PB1, BTN_PB2, BTN_COUNT } btn_id_t;

static ui_state_t     s_ui;                 /* PD5b state machine state */
static ui_state_t     s_prev;               /* last state the commands were derived from */
static TIM_HandleTypeDef *s_htim_enc = NULL;  /* TIM3 in encoder mode on PC6/PC7 */
static uint16_t       s_enc_last;           /* counter value already turned into events */
static display_info_t s_disp;               /* the words the screen should show now */
static display_info_t s_disp_drawn;         /* ... and the words on the panel: render() draws the difference */
static ui_state_t     s_ui_drawn;           /* the state the panel was last drawn from */
static uint8_t        s_screen_dirty = 1U;  /* full redraw wanted */
static uint8_t        s_status_dirty = 1U;  /* header / footer data came in: rebuild them */
/* Screen frame: 1 while the header and footer on the panel are the ones in
 * s_hdr_drawn / s_ftr_drawn. 0 at boot and whenever the debug screen has
 * drawn over the whole panel: the next screen then clears and draws all of
 * it. The four views are static to keep them off TonyTask's stack. */
static uint8_t        s_chrome_valid = 0U;
static sv_header_t    s_hdr_now;
static sv_header_t    s_hdr_drawn;
static sv_footer_t    s_ftr_now;
static sv_footer_t    s_ftr_drawn;

static StorageStatusMsg_t s_sto;
static uint8_t            s_sto_seen = 0U;       /* a storage status has arrived (SD chip "SD ..." until then) */
/* File list window (file_window.c): the 16 names around the selection.
 * s_sel_name is the RAW name of the selected file, the one PLAY sends to
 * Jack (never the '?'-cleaned copy the panel shows: a PC can write code
 * page 850 letters, and Jack must find the file by its real name).
 * s_sel_index is the file_index that name belongs to: when file_index
 * moves, sel_follow() takes the new name from the window, or "" until the
 * window around it arrives. */
static fw_window_t        s_win;
static char               s_sel_name[STORAGE_NAME_LEN];
static uint16_t           s_sel_index = 0U;
/* At most one window request is out at a time, so every reply is read
 * with the request that asked for it (s_win_req_last: it asked for the
 * last file). A request wanted while one is out waits (s_win_want) until
 * the reply is in, or until WIN_RETRY_MS have passed with none. */
static uint8_t            s_win_pending = 0U;    /* a request is out: wait for its reply */
static uint32_t           s_win_req_ms = 0U;     /* ... sent at this tick */
static uint8_t            s_win_req_last = 0U;   /* ... it asked for STORAGE_INDEX_LAST */
static uint8_t            s_win_want = 0U;       /* a request should go out when none is */
static uint8_t            s_win_want_retry = 0U; /* ... as LIST_FILES, the user's retry (File screen opened) */
/* PLAY after a recording plays that recording. Jack's status names the
 * file only while it is being recorded, so the RAW name is kept here
 * (cleared when RECORD_START is sent: only this recording's name counts).
 * It becomes the selection the moment REC stops the recording (Jack takes
 * RECORD_STOP before a PLAY_START sent after it, so PLAY plays it), or when
 * Jack's status says the recording has ended by itself (time up, fault). */
static char               s_rec_name[STORAGE_NAME_LEN];
static osMessageQueueId_t s_replyQueue = NULL;   /* StorageReply_t, len 2: file lists + the debug page's STATUS */
static osMessageQueueId_t s_jackReplyQueue = NULL; /* JackReply_t, len 1: ack for RECORD/PLAY_START (slide 24) */
static uint32_t           s_last_cmd_ms = 0U;    /* when the last command went to Jack (the 1 s rule, ui_follow_jack_idle) */
/* Footer notice, line 1: Jack's answer to the last REC, PLAY or DELETE
 * (or the pre-check's refusal of a REC or PLAY). Until s_notice_until
 * (SV_NOTICE_MS later) the footer says it, worded by sv_answer_notice()
 * on every footer build from his newest status, the same one the SD chip
 * shows, so the two always agree. The next RECORD_START or PLAY_START
 * ends it early. */
static uint8_t            s_notice_on = 0U;
static uint32_t           s_notice_until = 0U;
static sv_cmd_t           s_notice_cmd = SV_CMD_PLAY;    /* the command answered */
static uint8_t            s_notice_ok = 0U;              /* ... his ok */
static uint8_t            s_notice_detail = 0U;          /* ... his JackAckDetail_t */
static char               s_notice_name[STORAGE_NAME_LEN];   /* DELETE: the file, cleaned up for the panel */
/* Delete (delete_confirm.c): the two-tap confirm, the look File row 3 was
 * last drawn with, and the DELETE waiting for its answer in Jack's status:
 * its seq (0 = none) and its file's name, cleaned up for the notice. */
static delete_confirm_t   s_dc;
static uint8_t            s_dc_armed_drawn = 0U;
static uint8_t            s_del_seq = 0U;
static char               s_del_name[STORAGE_NAME_LEN];
/* No-SD pop-up (sd_popup.c): s_popup is what should show, the three after
 * it what the panel shows, so render() draws it, redraws it with new
 * words, or draws the screen under it again once it has closed. */
static sd_popup_t         s_popup;
static uint8_t            s_popup_drawn = 0U;
static sdp_reason_t       s_popup_drawn_reason = SDP_OK;
static uint8_t            s_popup_drawn_rec = 0U;

static uint8_t  s_btn_prev[BTN_COUNT];      /* each button's level at the last scan (1 = pressed) */
static uint32_t s_btn_last_ms[BTN_COUNT];   /* when its last press was counted (debounce, button_edge) */
/* Touch presses (touch_filter.c): down from the tap until the finger has
 * been off the glass for two samples, so one press is one tap. */
static touch_filter_t s_touch;
/* Last row tapped on a screen without its own highlight (Record, Play, ...),
 * drawn blue as press feedback until another row or screen is chosen. */
#define ROW_NONE        UI_ROW_NONE   /* 0xFF, display_logic.h */
static uint8_t     s_tapped_row = ROW_NONE;
static ui_screen_t s_tapped_screen = UI_SCREEN_HOME;
static uint8_t     s_tapped_row_drawn = ROW_NONE;
static uint32_t s_next_touch_ms = 0U;       /* when the next touch sample is due (every TOUCH_PERIOD_MS) */
/* Name last drawn on the Play screen. Sized for every string play_file_name()
 * returns: "No recordings" is 13 characters, which a DISPLAY_FILE_MAX (8.3 +
 * NUL) cache truncated, so the compare in render() never matched and the line
 * was redrawn on every 10 ms loop (visible shimmer). */
static char     s_play_name_drawn[DISPLAY_LABEL_MAX];
/* The File screen's "> NAME" line as last drawn (display_info_t does not
 * hold it), so it is redrawn only when the name changes. */
static char     s_file_line_drawn[DISPLAY_LABEL_MAX];
/* Record countdown, timed here rather than sent by Jack (no extra messages):
 * the clock starts when Jack first says he records, in his status or in
 * his RECORD_START ack, whichever Tony reads first (i.e. once the file is
 * open and capture is running), and stops when the UI leaves RECORDING. */
static uint8_t  s_rec_timing = 0U;
static uint32_t s_rec_start_ms = 0U;
static char     s_rec_text_drawn[8];
static uint8_t  s_rec_colour_drawn = 0xFFU;   /* the 'rec' flag the text was drawn with (grey / red) */
static uint16_t s_rec_fill_drawn = 0xFFFFU;
/* Volume screen redraw keys: which of -/+ shows pressed (blue), the level
 * bucket the speaker icon shows, the mute state both were drawn with, and
 * whether the battery-lockout notice is showing instead of the icon. */
static uint32_t s_vol_flash_until = 0U;
static uint8_t  s_vol_pressed_drawn = 0xFFU;
static uint8_t  s_vol_level_drawn = 0xFFU;
static uint8_t  s_vol_muted_drawn = 0xFFU;
static uint8_t  s_vol_locked_drawn = 0xFFU;
/* Hold-to-repeat, Volume screen only: the Volume +/- event being held
 * (EVENT_NONE when nothing repeats), when it fires next, and how often.
 * It repeats on the touch filter's HELD samples only, and stops once the
 * filter says the press is over. */
static ui_event_t s_hold_event = EVENT_NONE;
static uint32_t   s_hold_next_ms = 0U;
static uint8_t    s_hold_repeats = 0U;
/* Fault screen: s_fault_new = a fault has just been taken off faultQueue,
 * so the loop draws it at once, before the input scan (PD2 IR6), and then
 * starts the input guard that follows the fault screen opening and closing
 * (input_guard_start). */
static uint8_t    s_fault_new = 0U;
static uint8_t    s_input_guard = 0U;
static uint32_t   s_input_guard_until = 0U;
/* Screen saver (screen_saver.c). s_input_seen: this pass's scan saw an
 * input of any kind (a touch, also on a dead spot or a held finger; a
 * button edge or a held button; any change of the TIM3 count, also part
 * of a detent), s_enc_seen the TIM3 count it compared with. The SD BUSY
 * tag: whether it is on the frog now. */
static screen_saver_t s_saver;
static uint8_t        s_input_seen = 0U;
static uint16_t       s_enc_seen = 0U;
static uint8_t        s_saver_tag_drawn = 0U;
/* Hidden debug screen: the BACK-hold detector (debug_menu.c) and when the
 * Storage page next asks Jack for his full status. */
static debug_hold_t s_debug_hold;
static uint32_t     s_sto_req_next_ms = 0U;
/* Number (JackCmd_t.seq) of the last command sent to Jack: 1..255, never 0.
 * Jack echoes it in his ack and in his status (cmd_seq), so an answer can be
 * matched to its command: a status with this number describes Jack after
 * Tony's newest command (ui_follow_jack_idle, fx_na_update). */
static uint8_t      s_cmd_seq = 0U;
/* The number of the last RECORD_START or PLAY_START, the two commands Jack
 * acks. Tony's ack queue holds one ack, so an ack with another number
 * answers an older command: it is dropped, and can never act on a newer
 * REC or PLAY. */
static uint8_t      s_ack_seq = 0U;
/* The selected file named in the last SET_EFFECT or PLAY_START: Jack makes
 * that file's effect files first. Leaving the File screen with another
 * file selected tells him again. */
static char         s_fx_hint_name[STORAGE_NAME_LEN];

/* -------------------------------------------------------------------------- */
/* Messages out (owner-task pattern: never call into another module)          */
/* -------------------------------------------------------------------------- */
/* The number for the next command: 1..255, skipping 0 (0 = not numbered). */
static uint8_t next_cmd_seq(void)
{
    s_cmd_seq++;
    if (s_cmd_seq == 0U) {
        s_cmd_seq = 1U;
    }
    return s_cmd_seq;
}

/* Footer line 1 shows the answer to cmd for SV_NOTICE_MS (worded by
 * sv_answer_notice() whenever the footer is built). name: DELETE's file. */
static void notice_start(sv_cmd_t cmd, uint8_t ok, uint8_t detail, const char *name)
{
    s_notice_cmd    = cmd;
    s_notice_ok     = ok;
    s_notice_detail = detail;
    strncpy(s_notice_name, name, sizeof(s_notice_name) - 1U);   /* the rest is zero-filled */
    s_notice_name[sizeof(s_notice_name) - 1U] = '\0';
    sv_sanitize(s_notice_name, sizeof(s_notice_name));
    s_notice_on    = 1U;
    s_notice_until = osKernelGetTickCount() + SV_NOTICE_MS;
    s_status_dirty = 1U;
}

/* One command for Jack (jackCmdQueue, put timeout 10 ms). name is the RAW
 * 8.3 name PLAY_START and DELETE carry ("" for the others); index is
 * PLAY_START's list position, which Jack uses only when name is "". Every
 * command is numbered (seq). Returns that number. */
static uint8_t send_jack_named(JackCmdType_t type, const char *name, uint16_t index)
{
    JackCmd_t c = { .type = type, .effect = (uint8_t)s_ui.active_effect, .index = index,
                    .seconds = 0U, .name = "", .seq = next_cmd_seq(), .replyQueue = NULL };
    strncpy(c.name, name, sizeof(c.name) - 1U);         /* byte for byte: the name stays raw */
    /* Only RECORD_START and PLAY_START ask for an ack: if Jack refuses one
     * (no card, no files, bad WAV, busy), his ack drops the UI back to IDLE
     * at once and says why (jack_ack_in). DELETE and SET_EFFECT get none:
     * Tony's ack queue holds one ack, kept for a REC or PLAY pressed
     * meanwhile, so Jack answers them in his status (cmd_seq, cmd_ok,
     * cmd_detail), as he does every command Tony numbers. */
    if (type == JACK_CMD_RECORD_START || type == JACK_CMD_PLAY_START) {
        (void)osMessageQueueReset(s_jackReplyQueue);
        c.replyQueue = s_jackReplyQueue;
        s_ack_seq    = c.seq;                   /* the only ack taken from now on */
        /* A new REC or PLAY ends the notice about the last one, which would
         * hide the REC / PLAYING line; if Jack refuses this one too, his
         * ack starts a new notice. */
        if (s_notice_on) { s_notice_on = 0U; s_status_dirty = 1U; }
    }
    (void)App_RTOS_Put(jackCmdQueue, &c, 10U, &g_rtos_dropped.jack_cmd);
    s_last_cmd_ms = osKernelGetTickCount();
    return c.seq;
}

/* A command that names no file (REC, pause, resume, stop). */
static void send_jack(JackCmdType_t type)
{
    (void)send_jack_named(type, "", 0U);
}

/* PLAY_START for the selected file, by its raw name. With no name and no
 * window since the card came (it has only just gone in), Jack plays the
 * last file of the list (STORAGE_INDEX_LAST): never a name from the card
 * that was in before. */
static void send_play_start(void)
{
    uint16_t index = s_ui.file_index;
    if (s_sel_name[0] == '\0' && !fw_ever(&s_win)) {
        index = STORAGE_INDEX_LAST;
    }
    (void)send_jack_named(JACK_CMD_PLAY_START, s_sel_name, index);
    memcpy(s_fx_hint_name, s_sel_name, sizeof(s_fx_hint_name));   /* Jack starts with this file's effects */
}

/* The effect and the selected file go to Jack (JACK_CMD_SET_EFFECT, no
 * ack): idle or paused, he makes that file's effect files first; playing
 * or preparing, he switches to the effect at the same position. Tom no
 * longer gets the effect: effects are made ahead into effect files. */
static void send_set_effect(void)
{
    (void)send_jack_named(JACK_CMD_SET_EFFECT, s_sel_name, 0U);
    memcpy(s_fx_hint_name, s_sel_name, sizeof(s_fx_hint_name));
}

static void send_tom(TomCmdType_t type, uint8_t value)
{
    TomCmd_t c = { .type = type, .value = value };
    (void)App_RTOS_Put(tomCmdQueue, &c, 10U, &g_rtos_dropped.tom_cmd);
    (void)osThreadFlagsSet(TomTaskHandle, TOM_CMD_FLAG);
}

/* Jack's newest status as status_view.c and sd_popup.c take it. */
static sv_sd_in_t sd_in(void)
{
    const sv_sd_in_t sd = {
        .have_status  = s_sto_seen ? true : false,
        .card_present = s_sto.card_present ? true : false,
        .mounted      = s_sto.mounted ? true : false,
        .msc_mode     = s_sto.msc_mode ? true : false,
        .recording    = s_sto.recording ? true : false,
        .playing      = s_sto.playing,
        .status_text  = s_sto.status_text,
        .current_name = s_sto.current_name,
        .fx_busy      = s_sto.fx_busy ? true : false,   /* effect files being written: SD BUSY */
    };
    return sd;
}

/* REC or PLAY did nothing and the pop-up has just opened to say why for
 * SDP_SHOW_MS: the fault beep sounds once (Tom plays it whatever the volume
 * or mute, and also during the battery lockout, like every warning). */
static void popup_beep(void)
{
    send_tom(TOM_CMD_PLAY_TUNE, (uint8_t)TOM_TUNE_FAULT);
}

/* Jack refused a start: the pop-up over the screen showing, which the UI
 * stays on. sdp_open() opens nothing over the fault or debug screen. */
static void popup_show(uint8_t rec, sdp_reason_t why)
{
    if (sdp_open(&s_popup, why, rec ? true : false, s_ui.screen, osKernelGetTickCount())) {
        popup_beep();
    }
}

/* A REC or PLAY start that ui_process_event() has just made (emit_commands()
 * has not sent it yet): can the card take it, by Jack's newest status? If
 * not, nothing is sent and the press only says why (pop-up, beep, and the
 * footer notice, as for Jack's own refusal), and 1 is returned.
 * sdp_refuse() puts s_ui back on screen with playback, where it was before
 * the step (no "Recording" moment for a recording that never starts), and
 * opens the pop-up over that screen, the one the UI stays on. */
static uint8_t start_refused(sdp_start_t start, ui_screen_t screen, playback_state_t playback)
{
    if (start == SDP_START_NONE) return 0U;
    uint8_t      rec = (start == SDP_START_RECORD) ? 1U : 0U;
    sv_sd_in_t   sd  = sd_in();
    sdp_reason_t why = sdp_precheck(rec ? true : false, &sd, s_sto.file_count);
    if (why == SDP_OK) return 0U;
    notice_start(rec ? SV_CMD_RECORD : SV_CMD_PLAY, 0U, (uint8_t)SV_ACK_NONE, "");
    if (sdp_refuse(&s_popup, why, rec ? true : false, &s_ui, screen, playback, osKernelGetTickCount())) {
        popup_beep();
    }
    return 1U;
}

/* -------------------------------------------------------------------------- */
/* File list window (file_window.c) and the selected file                      */
/* -------------------------------------------------------------------------- */
/* A card Jack can list: in the slot, mounted, not handed to a PC. */
static bool card_listed(const StorageStatusMsg_t *st)
{
    return st->card_present && st->mounted && !st->msc_mode;
}

/* The selection follows file_index: after every change of file_index (a
 * knob step, Up / Down, a shorter list) the name PLAY sends is the name the
 * screen shows, taken from the window ("" until the window around it is
 * in; window_service() then asks for it). */
static void sel_follow(void)
{
    if (s_ui.file_index == s_sel_index) {
        return;
    }
    s_sel_index = s_ui.file_index;
    fw_sel_name(&s_win, s_ui.file_index, s_sel_name);
    dc_name_changed(&s_dc, s_sel_name);         /* an armed Delete was for the file before */
}

/* The card went (pulled, unmounted, handed to a PC): forget the selection
 * and the window, so the next card starts at its own last file. */
static void forget_selection(void)
{
    s_sel_name[0] = '\0';
    fw_invalidate(&s_win);
    dc_name_changed(&s_dc, s_sel_name);
}

/* A recording has just ended (REC stopped it, or Jack's status says so):
 * select it by its name, which the next window reply turns into its list
 * position. Nothing if no recording was named. */
static void select_recording(void)
{
    if (s_rec_name[0] == '\0') {
        return;
    }
    memcpy(s_sel_name, s_rec_name, sizeof(s_sel_name));
    dc_name_changed(&s_dc, s_sel_name);
}

/* Ask Jack for the window around the selection, as soon as no request is
 * out. retry: the user opened the File screen, which is also the retry
 * (Jack clears a Card Error / Card Full and rescans: STORAGE_REQ_LIST_FILES);
 * every other request only reads the list he has (STORAGE_REQ_FILE_NAMES). */
static void window_ask(uint8_t retry)
{
    s_win_want = 1U;
    if (retry) {
        s_win_want_retry = 1U;
    }
}

/* Send the waiting request. The window is centred on the selected file's
 * name when Jack finds it (so a changed list keeps the same file selected),
 * else on file_index; with no name and no window since the card came, on
 * the last file of the list. */
static void window_send(void)
{
    StorageReq_t req = { .type = s_win_want_retry ? STORAGE_REQ_LIST_FILES : STORAGE_REQ_FILE_NAMES,
                         .index = s_ui.file_index, .anchor = "", .replyQueue = s_replyQueue };
    memcpy(req.anchor, s_sel_name, sizeof(req.anchor));
    s_win_req_last = (s_sel_name[0] == '\0' && !fw_ever(&s_win)) ? 1U : 0U;
    if (s_win_req_last) {
        req.index = STORAGE_INDEX_LAST;
    }
    (void)osMessageQueueReset(s_replyQueue);
    if (App_RTOS_Put(storageReqQueue, &req, 10U, &g_rtos_dropped.storage_req) != osOK) {
        return;                                 /* queue full: try again on the next pass */
    }
    s_win_want       = 0U;
    s_win_want_retry = 0U;
    s_win_pending    = 1U;
    s_win_req_ms     = osKernelGetTickCount();
}

/* What the screen needs from Jack's list now: no window yet after boot or
 * a new card (its last file is selected), a window from before the list
 * changed (list_gen moved on) or no name for the selection on the File and
 * Play screens, or a selection near the window's edge. */
static void window_want_from_state(void)
{
    if (!s_sto_seen || !card_listed(&s_sto) || s_ui.file_count == 0U) {
        return;                                 /* nothing to list */
    }
    if (!fw_ever(&s_win) && s_sel_name[0] == '\0') {
        window_ask(0U);
        return;
    }
    uint8_t list_shown = (s_ui.screen == UI_SCREEN_FILE || s_ui.screen == UI_SCREEN_PLAY) ? 1U : 0U;
    if (list_shown && (fw_stale(&s_win, s_sto.list_gen) || s_sel_name[0] == '\0')) {
        window_ask(0U);
        return;
    }
    if (fw_wants(&s_win, s_ui.file_index)) {
        window_ask(0U);
    }
}

/* Once per loop pass: one window request at a time. A request with no reply
 * after WIN_RETRY_MS is taken as lost (Jack puts replies with timeout 0). */
static void window_service(void)
{
    if (s_win_pending) {
        if ((osKernelGetTickCount() - s_win_req_ms) < WIN_RETRY_MS) {
            return;                             /* still waiting for Jack */
        }
        s_win_pending = 0U;                     /* no reply within 1 s: ask again */
    }
    window_want_from_state();
    if (s_win_want) {
        window_send();
    }
}

/* Is the file at list position index of the window the selected file
 * (s_sel_name)? */
static bool is_selected_name_at(uint16_t index)
{
    const char *name = fw_name(&s_win, index);   /* NULL outside the window */
    return name != NULL && strncmp(name, s_sel_name, sizeof(s_sel_name)) == 0;
}

/* A window from Jack: keep it and put the selection on it. Ignored when
 * the card went meanwhile (by his newest status or the reply's own): it
 * would be the old card's names. */
static void window_reply(const StorageReply_t *rep)
{
    s_win_pending = 0U;
    if (!s_sto_seen || !card_listed(&s_sto) || !card_listed(&rep->status)) {
        return;
    }
    fw_apply(&s_win, rep->first, rep->count, rep->total, rep->list_gen);
    for (uint8_t i = 0U; i < rep->count && i < STORAGE_MAX_LISTED_FILES; i++) {
        fw_apply_name(&s_win, i, rep->names[i]);
    }
    /* Known limit: rep->storage_result is not checked. If Jack could not
     * read the card's root for this reply, the File screen says "No files
     * found" until his next status, or until Files is opened again (which
     * rescans). */
    s_ui.file_count = rep->total;
    /* found: where the request's anchor (the file selected when it went
     * out) is now. The selection follows it only if that file is still the
     * selected one. If not, the user has moved on since (a knob step or Up /
     * Down while Jack answered; he can take ~100 ms), or this is a late
     * answer to an older request (after a 1 s retry): file_index then stays
     * where it is, only clamped below. Known limit: if Jack's list also
     * changed in that time (a new file earlier in the list, say), that
     * position can now hold the file next to the one stepped to. */
    if (rep->found != STORAGE_INDEX_NONE && is_selected_name_at(rep->found)) {
        s_ui.file_index = rep->found;           /* the anchor: the selected file, wherever it is now */
    } else if (s_win_req_last && rep->total > 0U) {
        s_ui.file_index = (uint16_t)(rep->total - 1U);   /* boot or a new card: the last file */
    } else if (s_ui.file_index >= rep->total) {
        s_ui.file_index = (rep->total > 0U) ? (uint16_t)(rep->total - 1U) : 0U;
    }
    s_sel_index = s_ui.file_index;
    fw_sel_name(&s_win, s_ui.file_index, s_sel_name);
    dc_name_changed(&s_dc, s_sel_name);
    s_prev.file_count = s_ui.file_count;
}

/* The selected file's name for the panel: a copy of the raw s_sel_name with
 * the bytes the font has no glyph for made '?', or "..." while its window
 * is still on the way. */
static const char *sel_name_shown(void)
{
    static char shown[STORAGE_NAME_LEN];
    if (s_sel_name[0] == '\0') {
        return "...";
    }
    memcpy(shown, s_sel_name, sizeof(shown));
    sv_sanitize(shown, sizeof(shown));
    return shown;
}

/* -------------------------------------------------------------------------- */
/* Delete (delete_confirm.c): two taps, then JACK_CMD_DELETE, answered in      */
/* Jack's status                                                               */
/* -------------------------------------------------------------------------- */
/* A tap on Delete counts only for a file that is listed and named, on a
 * card Jack has mounted and not handed to a PC, and not while recording
 * (Jack refuses a delete then). */
static bool delete_allowed(void)
{
    return s_ui.file_count > 0U && s_sel_name[0] != '\0' && s_sto_seen && card_listed(&s_sto) &&
           !s_sto.recording && s_ui.playback != PLAYBACK_RECORDING;
}

/* The Delete row was tapped: the first tap arms it, a second tap 0.5 to 3 s
 * later sends JACK_CMD_DELETE for the ARMED name, with no reply queue (the
 * answer comes in Jack's status, delete_answered()). */
static void delete_row_pressed(void)
{
    char armed_name[DC_NAME_LEN];

    if (!delete_allowed()) {
        dc_cancel(&s_dc);
        return;
    }
    if (dc_press(&s_dc, osKernelGetTickCount(), s_sel_name, armed_name) != DC_PRESS_CONFIRMED) {
        return;                                 /* armed, or too soon: wait for the next tap */
    }
    s_del_seq = send_jack_named(JACK_CMD_DELETE, armed_name, 0U);
    memcpy(s_del_name, armed_name, sizeof(s_del_name));
    sv_sanitize(s_del_name, sizeof(s_del_name));
}

/* Jack's status carries the DELETE's seq: he has stopped any playback,
 * deleted (or refused) and rescanned. The footer says what happened, and
 * the window is asked for again: the list has closed up, so the same
 * position now holds the next file. The transport is not touched here:
 * when DELETE is still Tony's newest command, the same status takes the UI
 * to idle (ui_follow_jack_idle); a PLAY pressed meanwhile is newer, so the
 * UI stays playing and that PLAY's own answer follows. */
static void delete_answered(const StorageStatusMsg_t *st)
{
    notice_start(SV_CMD_DELETE, st->cmd_ok, st->cmd_detail, s_del_name);
    window_ask(0U);
    s_del_seq = 0U;
}

/* Debug screen, Storage page: Jack's full status (bus width, capacity, last
 * error) once a second. The reply comes back on the same private queue as
 * the file lists; drain_queues() tells them apart by rep.type. */
static void request_storage_status(void)
{
    StorageReq_t req = { .type = STORAGE_REQ_STATUS, .replyQueue = s_replyQueue };
    (void)App_RTOS_Put(storageReqQueue, &req, 10U, &g_rtos_dropped.storage_req);
}

/* -------------------------------------------------------------------------- */
/* State diff: ui_state_t change -> message (Appendix C)                       */
/* -------------------------------------------------------------------------- */
/* Appendix C: ui_state_t change -> message.
 * Why a diff: ui_process_event() is pure logic (host-tested, no RTOS); it
 * only changes s_ui. The loop keeps the state from before each event
 * (s_prev), and this function turns every field that changed into a
 * message for the task that owns that job: the transport and the effect
 * go to Jack (JackStorageTask: the SD card, recording, playback and the
 * effect files), volume and mute to Tom (TomTask: the speaker). So the
 * state machine never needs to know about queues or other tasks.
 * Commands that are not a state change (Delete, a File screen select
 * while a file plays, the debug screen's) are sent where they happen. */
static void emit_commands(const ui_state_t *prev, const ui_state_t *now, ui_event_t ev)
{
    if (prev->playback != now->playback) {
        if (prev->playback == PLAYBACK_IDLE && now->playback == PLAYBACK_RECORDING) {
            s_rec_name[0] = '\0';                   /* only this recording's name will count */
            send_jack(JACK_CMD_RECORD_START);
        } else if (prev->playback == PLAYBACK_RECORDING && now->playback == PLAYBACK_IDLE) {
            send_jack(JACK_CMD_RECORD_STOP);
            select_recording();                     /* PLAY from now on plays the new recording */
        } else if (prev->playback == PLAYBACK_IDLE && now->playback == PLAYBACK_PLAYING) {
            send_play_start();
        } else if (prev->playback == PLAYBACK_PLAYING && now->playback == PLAYBACK_PAUSED) {
            send_jack(JACK_CMD_PLAY_PAUSE);
        } else if (prev->playback == PLAYBACK_PAUSED && now->playback == PLAYBACK_PLAYING) {
            send_jack(JACK_CMD_PLAY_RESUME);
        } else if ((prev->playback == PLAYBACK_PLAYING || prev->playback == PLAYBACK_PAUSED) &&
                   now->playback == PLAYBACK_IDLE) {
            send_jack(JACK_CMD_PLAY_STOP);
        } else if ((prev->playback == PLAYBACK_PLAYING || prev->playback == PLAYBACK_PAUSED) &&
                   now->playback == PLAYBACK_RECORDING) {
            /* Playback loops forever (no Stop on the Play screen), so Record
             * replaces it. Jack takes his queue in order: stop, then record. */
            send_jack(JACK_CMD_PLAY_STOP);
            s_rec_name[0] = '\0';
            send_jack(JACK_CMD_RECORD_START);
        }
    } else if (ev == EVENT_PLAY_REPLAY && now->playback == PLAYBACK_PLAYING) {
        send_jack(JACK_CMD_PLAY_STOP);              /* replay = stop + start */
        send_play_start();
    }

    if (prev->active_effect != now->active_effect) {
        send_set_effect();                          /* UiEffect_t mirrors ui_effect_t */
    } else if (prev->screen == UI_SCREEN_FILE && now->screen != UI_SCREEN_FILE &&
               strncmp(s_sel_name, s_fx_hint_name, sizeof(s_sel_name)) != 0) {
        /* The File screen closes with another file picked: Jack makes its
         * effect files first, so the effect the user tries next is ready. */
        send_set_effect();
    }
    if (prev->muted != now->muted) {
        send_tom(TOM_CMD_SET_MUTE, now->muted ? 1U : 0U);
    }
    if (prev->volume != now->volume) {
        /* Raw level, not ui_get_effective_volume(): Tom keeps volume and mute
         * separately (TOM_CMD_SET_MUTE gates the output), so sending the
         * muted "0" would leave him at volume 0 after the next unmute. */
        send_tom(TOM_CMD_SET_VOLUME, now->volume);
    }
    if (prev->screen != now->screen && prev->screen != UI_SCREEN_FAULT &&
        (now->screen == UI_SCREEN_FILE || now->screen == UI_SCREEN_PLAY)) {
        /* slide 24: our own reply queue; Play shows the selected name.
         * Closing the fault screen only uncovers File/Play again: that is
         * not the user opening it, so no retry/rescan request. */
        window_ask((now->screen == UI_SCREEN_FILE) ? 1U : 0U);
    }
}

/* -------------------------------------------------------------------------- */
/* Inputs                                                                      */
/* -------------------------------------------------------------------------- */
/* The four buttons are plain GPIO inputs with pull-ups (main.c): a press
 * pulls the pin LOW, so LOW = pressed. They raise no interrupt, which is
 * why the task polls them on every 10 ms pass. */
static uint8_t button_pressed(GPIO_TypeDef *port, uint16_t pin)
{
    return (HAL_GPIO_ReadPin(port, pin) == GPIO_PIN_RESET) ? 1U : 0U;
}

/* Non-blocking debounced falling-edge detector (kept from the demo).
 * Debounce: a button's metal contacts bounce, opening and closing a few
 * times in the first milliseconds of a press. So a press counts only on
 * the change from released to pressed (the falling edge of the pin), and
 * only if the last counted press of that button was BUTTON_DEBOUNCE_MS
 * (30 ms) or more ago: the bounces of one press count once. Non-blocking:
 * it compares this scan's sample with the last one and never waits. */
static uint8_t button_edge(btn_id_t id, GPIO_TypeDef *port, uint16_t pin)
{
    uint8_t now = button_pressed(port, pin);
    uint8_t fell = 0U;
    uint32_t t = osKernelGetTickCount();
    if (now && !s_btn_prev[id] && (t - s_btn_last_ms[id]) >= BUTTON_DEBOUNCE_MS) {
        fell = 1U;
        s_btn_last_ms[id] = t;
    }
    s_btn_prev[id] = now;
    return fell;
}

/* Resistive panel: switch pin modes, settle, sample (ADC through tony_ports).
 *
 * Untouched, the sense plate is connected to nothing and the ADC reads
 * whatever charge is left on it — often inside the 100..4000 "pressed"
 * window, which produced phantom taps ("tap 319,89" with nobody touching).
 * An analog-mode pin has no pull resistors (RM0383), so the pull-up goes on
 * the OTHER end of the sense plate (a plain input): through the plate's few
 * hundred ohms it holds the whole sense plate at 3.3 V, i.e. ~4095 counts,
 * safely above TOUCH_NO_PRESS_THRESHOLD_HIGH. A real touch connects the
 * sense plate to the driven plate through a much lower resistance than the
 * ~40 k internal pull-up, so the reading is still the touch position. */
static void touch_set_pin(GPIO_TypeDef *port, uint16_t pin, uint32_t mode, uint32_t pull)
{
    GPIO_InitTypeDef g = {0};
    g.Pin = pin; g.Mode = mode; g.Pull = pull; g.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(port, &g);
}

static uint16_t touch_read_x(void)
{
    touch_set_pin(GPIOC, GPIO_PIN_1, GPIO_MODE_OUTPUT_PP, GPIO_NOPULL); HAL_GPIO_WritePin(GPIOC, GPIO_PIN_1, GPIO_PIN_SET);
    touch_set_pin(GPIOC, GPIO_PIN_5, GPIO_MODE_OUTPUT_PP, GPIO_NOPULL); HAL_GPIO_WritePin(GPIOC, GPIO_PIN_5, GPIO_PIN_RESET);
    touch_set_pin(GPIOC, GPIO_PIN_0, GPIO_MODE_ANALOG, GPIO_NOPULL);    /* X+ sense */
    touch_set_pin(GPIOC, GPIO_PIN_4, GPIO_MODE_INPUT, GPIO_PULLUP);     /* X- : parks the X plate at 3.3 V when untouched */
    osDelay(2U);                                  /* panel settle */
    return TonyPorts_AdcRead(ADC_CHANNEL_10);
}

static uint16_t touch_read_y(void)
{
    touch_set_pin(GPIOC, GPIO_PIN_0, GPIO_MODE_OUTPUT_PP, GPIO_NOPULL); HAL_GPIO_WritePin(GPIOC, GPIO_PIN_0, GPIO_PIN_SET);
    touch_set_pin(GPIOC, GPIO_PIN_4, GPIO_MODE_OUTPUT_PP, GPIO_NOPULL); HAL_GPIO_WritePin(GPIOC, GPIO_PIN_4, GPIO_PIN_RESET);
    touch_set_pin(GPIOC, GPIO_PIN_1, GPIO_MODE_ANALOG, GPIO_NOPULL);    /* Y+ sense */
    touch_set_pin(GPIOC, GPIO_PIN_5, GPIO_MODE_INPUT, GPIO_PULLUP);     /* Y- : parks the Y plate at 3.3 V when untouched */
    osDelay(2U);
    return TonyPorts_AdcRead(ADC_CHANNEL_11);
}

/* Two samples per axis, through the press filter (touch_filter.c): returns
 * TOUCH_ACT_TAP with screen pixels on the first good sample of a press,
 * TOUCH_ACT_HELD on its later good samples, TOUCH_ACT_NONE otherwise. One
 * bad sample no longer ends the press: it used to, and the same finger then
 * tapped again on the screen its first tap had opened. touch_calibrate()
 * gives the pixel in the glass's own 320 x 240 frame, in which X reads
 * left-to-right but the Y plate reads bottom-to-top (high ADC at the top
 * edge); touch_calibrate() itself needs MIN < MAX. touch_panel_to_screen()
 * then flips Y and turns the point to the portrait screen with the panel's
 * own rotation (UI_PORTRAIT_ROTATION), so the touch always follows the
 * picture. */
static touch_action_t touch_tap(uint16_t *px, uint16_t *py)
{
    uint16_t x1 = touch_read_x();
    uint16_t x2 = touch_read_x();
    uint16_t y1 = touch_read_y();
    uint16_t y2 = touch_read_y();

    touch_action_t act = touch_filter_update(&s_touch, touch_classify(x1, y1, x2, y2));
    if (act != TOUCH_ACT_TAP) return act;         /* held, or no new press: no position needed */

    uint16_t cal_x, cal_y;
    touch_calibrate((uint16_t)((x1 + x2) / 2U), (uint16_t)((y1 + y2) / 2U), &cal_x, &cal_y);
    if (!touch_panel_to_screen(UI_PORTRAIT_ROTATION, cal_x, cal_y, px, py)) return TOUCH_ACT_NONE;
    return TOUCH_ACT_TAP;
}

/* Any of the four buttons is down (the levels button_edge() sampled). */
static uint8_t button_held(void)
{
    for (uint8_t i = 0U; i < (uint8_t)BTN_COUNT; i++) {
        if (s_btn_prev[i]) return 1U;
    }
    return 0U;
}

/* Collect at most a few events per scan, in priority order.
 * Order: the four buttons, the BACK-hold detector, the encoder, then the
 * touch panel. At most max events (the loop passes 4); what does not fit
 * waits for the next pass, 10 ms later: a button not read keeps its edge,
 * extra encoder clicks stay in the TIM3 count, and the touch sample is
 * simply taken next time. s_input_seen tells the screen saver whether
 * anything was touched at all. */
static uint8_t scan_inputs(ui_event_t *out, uint8_t max)
{
    uint8_t n = 0U;
    s_input_seen = 0U;
    if (n < max && button_edge(BTN_PB0, GPIOB, GPIO_PIN_0)) out[n++] = EVENT_GO_HOME;
    if (n < max && button_edge(BTN_PB1, GPIOB, GPIO_PIN_1)) out[n++] = EVENT_BTN_PLAYPAUSE;
    if (n < max && button_edge(BTN_PB2, GPIOB, GPIO_PIN_2)) out[n++] = EVENT_BTN_RECORD;
    if (n < max && button_edge(BTN_PA8, GPIOA, GPIO_PIN_8)) out[n++] = EVENT_MUTE_TOGGLE;
    if (button_held()) s_input_seen = 1U;              /* a press, or a button still held */

    /* Hidden debug screen: BACK held for 2 s, all of it on Home
     * (debug_menu.c). The detector is fed on every scan, also on the fault
     * and debug screens and during the input guard, with on_home as it is
     * BEFORE this scan's events are handled. So the BACK press that leaves
     * the debug screen or closes a fault screen is still off Home at its
     * first update (its EVENT_GO_HOME above is only collected, not handled
     * yet) and can never (re)open the debug screen; nor can a hold during
     * which a fault screen opens. The level is the PB0 sample button_edge()
     * has just taken: a second read could catch the press edge bouncing
     * open, and the detector would then first see that press once Home is
     * shown. It opens here, before the encoder and touch are read, so a
     * detent from this same scan already moves the debug cursor. While the
     * screen saver shows, Home is hidden under it: a 2 s BACK used to wake
     * it is a press off Home, so it never opens the debug screen. */
    uint8_t on_home = (s_ui.screen == UI_SCREEN_HOME && !ss_showing(&s_saver)) ? 1U : 0U;
    if (debug_hold_update(&s_debug_hold, s_btn_prev[BTN_PB0], on_home, osKernelGetTickCount()) != 0U) {
        ui_enter_debug(&s_ui);
    }

    /* TIM3 counts every quadrature edge in hardware, so detents turned while
     * this task was busy (rendering, touch, preempted) are still in the count.
     * Clockwise counts up. Whole detents become events; a part-turned detent
     * stays in the count for the next scan. uint16_t wrap is intended. Any
     * change of the count, also part of a detent, is an input for the
     * screen saver.
     * Quadrature: the knob's two contacts (PC6, PC7) switch a quarter of a
     * cycle apart. In encoder mode the timer counts every change of either
     * contact, up or down by the other contact's level, i.e. the direction:
     * 4 counts per click (ENC_COUNTS_PER_DETENT). A bounce of one contact
     * counts one step and then the same step back, so it cancels out. */
    uint16_t enc_count = (uint16_t)__HAL_TIM_GET_COUNTER(s_htim_enc);
    if (enc_count != s_enc_seen) {
        s_input_seen = 1U;
        s_enc_seen   = enc_count;
    }
    int16_t d = (int16_t)(enc_count - s_enc_last);
    while (n < max && d >= ENC_COUNTS_PER_DETENT) {
        out[n++] = EVENT_VOLUME_UP;
        s_enc_last = (uint16_t)(s_enc_last + ENC_COUNTS_PER_DETENT);
        d -= ENC_COUNTS_PER_DETENT;
    }
    while (n < max && d <= -ENC_COUNTS_PER_DETENT) {
        out[n++] = EVENT_VOLUME_DOWN;
        s_enc_last = (uint16_t)(s_enc_last - ENC_COUNTS_PER_DETENT);
        d += ENC_COUNTS_PER_DETENT;
    }

    ui_event_t e;

    /* Touch: one sample every TOUCH_PERIOD_MS (40 ms), not on every pass. A
     * sample switches the panel's pins four times and waits 2 ms after each
     * for the sheets to settle (touch_read_x, touch_read_y), so it holds the
     * loop up for up to about 8 ms; 25 samples a second are plenty for a
     * tap. (int32_t)(now - next) >= 0 means "now has reached next", and it
     * stays right when the 32-bit millisecond count wraps (every ~49 days). */
    uint32_t now = osKernelGetTickCount();
    if (n < max && (int32_t)(now - s_next_touch_ms) >= 0) {
        s_next_touch_ms = now + TOUCH_PERIOD_MS;
        uint16_t px, py;
        touch_action_t act = touch_tap(&px, &py);
        if (act != TOUCH_ACT_NONE) s_input_seen = 1U;   /* a tap or a held finger, also on a dead spot */
        if (ss_showing(&s_saver)) return n;            /* the frog shows: a touch only wakes it, unmapped */
        if (act == TOUCH_ACT_TAP) {
            /* A tap on the pop-up's box only closes it, so nothing hidden
             * under the box acts. A tap off the box closes it too: here
             * when it hits nothing (the Battery screen, the header),
             * otherwise as every input does (Tony_TaskEntry), and acts. */
            e = sdp_tap_on_box(&s_popup, px, py) ? EVENT_NONE : touch_get_event(px, py, s_ui.screen);
            if (e == EVENT_NONE) (void)sdp_close_on_input(&s_popup);
            s_hold_event = EVENT_NONE;
            if (s_ui.screen == UI_SCREEN_VOLUME && (e == EVENT_VOLUME_UP || e == EVENT_VOLUME_DOWN)) {
                s_hold_event = e;
                s_vol_flash_until = now + VOL_PRESS_FLASH_MS;
                s_hold_next_ms = now + VOL_REPEAT_DELAY_MS;
                s_hold_repeats = 0U;
            }
            if (e != EVENT_NONE) {
                out[n++] = e;
                if (px >= MENU_X && px < MENU_X + MENU_W && py >= MENU_Y0) {
                    uint16_t off = (uint16_t)(py - MENU_Y0);
                    if ((off % MENU_GAP) < MENU_H) {      /* same hit rule as touch_region.c */
                        s_tapped_row = (uint8_t)(off / MENU_GAP);
                        s_tapped_screen = s_ui.screen;
                    }
                }
            }
        } else if (s_touch.down == 0U) {
            s_hold_event = EVENT_NONE;                    /* finger lifted (two released samples) */
        } else if (act == TOUCH_ACT_HELD && s_hold_event != EVENT_NONE && s_ui.screen == UI_SCREEN_VOLUME &&
                   (int32_t)(now - s_hold_next_ms) >= 0) {
            out[n++] = s_hold_event;                      /* still held: repeat */
            if (s_hold_repeats < VOL_REPEAT_ACCEL_AFTER) s_hold_repeats++;
            s_hold_next_ms = now + ((s_hold_repeats < VOL_REPEAT_ACCEL_AFTER) ? VOL_REPEAT_SLOW_MS
                                                                              : VOL_REPEAT_FAST_MS);
        }
    }
    return n;
}

/* -------------------------------------------------------------------------- */
/* Queue drains (newest wins, timeout 0)                                      */
/* -------------------------------------------------------------------------- */
/* The header's three flags from BrendonTask's 1 Hz power snapshot. No new
 * message or field: this is TonyTask's own copy of the PowerDebugMsg_t it
 * drains anyway. All three are false before the first snapshot and once
 * BrendonTask has been quiet for 3 s, so a stale SOC OVERRIDE, ON USB POWER
 * or CHARGER FAULT tag never stays. */
static void power_flags_update(void)
{
    PowerDebugMsg_t p;
    bool soc_override = false, ext_power = false, charger_fault = false;
    if (TonyDebug_PowerSnapshot(&p)) {
        soc_override  = p.soc_override ? true : false;
        ext_power     = p.power_good ? true : false;    /* input power good: USB plugged in */
        charger_fault = (p.charger_state == (uint8_t)CHARGER_STATE_FAULT) ? true : false;
    }
    if (soc_override != s_ui.battery_soc_override || ext_power != s_ui.battery_ext_power ||
        charger_fault != s_ui.battery_charger_fault) {
        s_ui.battery_soc_override  = soc_override;
        s_ui.battery_ext_power     = ext_power;
        s_ui.battery_charger_fault = charger_fault;
        s_status_dirty = 1U;
    }
}

/* Jack's newest status (storageStatusQueue, newest wins): the card, his
 * file list and his transport, as he sees them now. */
static void storage_status_in(const StorageStatusMsg_t *st)
{
    uint8_t was_recording = s_sto.recording;
    /* PLAY after a recording: keep its name, RAW, while Jack records
     * (before the clean-up below changes the copy in s_sto). */
    if (st->recording) {
        memcpy(s_rec_name, st->current_name, sizeof(s_rec_name));
        s_rec_name[sizeof(s_rec_name) - 1U] = '\0';
    }
    s_sto = *st;
    /* Texts from the card go to the panel's 96-glyph font: any other
     * byte becomes '?' (and every text ends in a NUL). */
    sv_sanitize(s_sto.status_text, sizeof(s_sto.status_text));
    sv_sanitize(s_sto.current_name, sizeof(s_sto.current_name));
    sv_sanitize(s_sto.fx_job_name, sizeof(s_sto.fx_job_name));     /* the debug Storage page's FX job row */
    s_sto_seen = 1U;
    if (!card_listed(st)) {
        forget_selection();                        /* no card to list: the next one starts afresh */
    } else if (was_recording && !st->recording) {
        /* The recording has ended (stop, time up, fault). Jack has closed
         * the file and rescanned the card before publishing this status
         * (storage_record_finish), so his list holds it. */
        select_recording();
        window_ask(0U);
    }
    s_ui.sd_status  = !st->card_present ? SD_STATUS_NO_CARD : (st->mounted ? SD_STATUS_OK : SD_STATUS_ERROR);
    s_ui.file_count = st->file_count;
    /* "Preparing 45%": Jack makes the effect file PLAY waits for. */
    s_ui.prep_pct   = (st->playing == JACK_PLAY_PREPARING) ? st->prep_pct : UI_PREP_NONE;
    /* The REC clock: Jack records. This status usually starts it: he
     * publishes it just before his RECORD_START ack (which may be lost). */
    if (ui_rec_clock_start(s_ui.playback, st->recording != 0U, s_rec_timing != 0U)) {
        s_rec_timing   = 1U;
        s_rec_start_ms = osKernelGetTickCount();
    }
    if (s_ui.file_index >= s_ui.file_count && s_ui.file_count > 0U) {
        s_ui.file_index = (uint16_t)(s_ui.file_count - 1U);   /* the list got shorter */
    }
    sel_follow();
    if (s_del_seq != 0U) {
        if (st->cmd_seq == s_del_seq) {
            delete_answered(st);
        } else if (st->cmd_seq == s_cmd_seq) {
            s_del_seq = 0U;     /* a newer command was handled first: its notice wins, the list still updates */
        }
    }
    /* Jack is the authority on transport state: if he is idle (finished,
     * refused, card pulled, a delete stopped it), follow him at once when
     * this status comes after Tony's newest command (its seq), else only
     * UI_CMD_RECONCILE_MS after it: an older "idle" must not undo a press. */
    if (ui_follow_jack_idle(s_ui.playback, st->recording != 0U, st->playing, st->cmd_seq == s_cmd_seq,
                            osKernelGetTickCount() - s_last_cmd_ms)) {
        s_ui.playback = PLAYBACK_IDLE;
        s_prev.playback = PLAYBACK_IDLE;           /* no command for this transition */
    }
    s_ui.error_active = (st->card_present && !st->mounted && !st->msc_mode) ? true : false;
    s_status_dirty = 1U;
}

/* Jack's ack of the last RECORD_START or PLAY_START (Tony's ack queue).
 * An ack with another seq answers an older command: dropped. A refusal:
 * footer line 1 says why for SV_NOTICE_MS (no card, card on a PC, card
 * full, no recordings, ...), also when the UI is idle again by now: the
 * press still did nothing. sv_answer_notice() decides the words, from the
 * status he published just before this ack. Returns 1 when the no-SD
 * pop-up should open too (drain_queues opens it after the faults). */
static uint8_t jack_ack_in(const JackReply_t *ack)
{
    if (ack->seq != s_ack_seq) {
        return 0U;                                          /* an old ack: dropped */
    }
    if (ack->type != JACK_CMD_RECORD_START && ack->type != JACK_CMD_PLAY_START) {
        return 0U;
    }
    sv_cmd_t    cmd = (ack->type == JACK_CMD_RECORD_START) ? SV_CMD_RECORD : SV_CMD_PLAY;
    sv_sd_in_t  sd  = sd_in();
    sv_notice_t n;
    sv_answer_notice(cmd, ack->ok ? true : false, ack->detail, &sd, s_sto.file_count, "", &n);
    if (n.text[0] != '\0') {
        notice_start(cmd, ack->ok, ack->detail, "");       /* a refusal, or "NO FX FOR THIS FILE" */
    } else if (s_notice_on) {
        s_notice_on    = 0U;                                /* accepted: an older notice ends */
        s_status_dirty = 1U;
    }
    if (!ack->ok && s_ui.playback != PLAYBACK_IDLE) {
        s_ui.playback = PLAYBACK_IDLE;                      /* Jack refused the start: back to idle */
        s_prev.playback = PLAYBACK_IDLE;                    /* no command for this transition */
        s_status_dirty = 1U;
    } else if (ack->ok) {
        if (ui_rec_clock_start(s_ui.playback, cmd == SV_CMD_RECORD, s_rec_timing != 0U)) {
            s_rec_timing   = 1U;                            /* the file is open, capture runs */
            s_rec_start_ms = osKernelGetTickCount();
        }
        /* Jack has processed the command (he publishes status BEFORE
         * replying), so every status from now on is post-command: end the
         * reconcile blackout (the seq rule already does, unless a newer
         * command is on its way). */
        s_last_cmd_ms = osKernelGetTickCount() - UI_CMD_RECONCILE_MS - 1U;
    }
    if (cmd == SV_CMD_PLAY && !ack->ok && ack->detail == (uint8_t)JACK_ACK_NOT_FOUND) {
        window_ask(0U);                                     /* the list changed: the window again */
    }
    return n.popup ? 1U : 0U;
}

/* First thing in every loop pass: take what the other tasks have sent.
 * Every get has timeout 0: TonyTask must never wait on a queue, or the
 * buttons would go unread. batteryQueue, storageStatusQueue and
 * powerDebugQueue are one deep and their senders replace the old message
 * (newest wins), so one get takes the latest. faultQueue is emptied:
 * each fault is sent only once, so none may be left behind. */
static void drain_queues(void)
{
    BatteryMsg_t b;
    if (osMessageQueueGet(batteryQueue, &b, NULL, 0U) == osOK) {
        s_ui.battery_mv  = b.voltage_mV;
        /* The gauge's SoC as it is, also when the reading is not valid: the
         * header then shows " --%" instead of a guess from the voltage. */
        s_ui.battery_pct = b.soc_pct;
        /* Battery screen (PD2 B9): the current now and its 2-minute
         * average, Brendon's time estimates (65535 = no estimate yet, shown
         * --:--), charging and validity. display_logic turns them into the six
         * lines; render() redraws only the lines whose text changed, so
         * the screen does not flicker. current_mA, the gauge's own slow
         * average, is shown by the debug screen (PowerDebugMsg_t). */
        s_ui.battery_ma_now   = b.current_now_mA;
        s_ui.battery_ma_avg   = b.current_avg_mA;
        s_ui.battery_tte_min  = b.tte_min;
        s_ui.battery_ttf_min  = b.ttf_min;
        s_ui.battery_charging = b.charging ? true : false;
        s_ui.battery_valid    = b.valid ? true : false;
        /* The power header's colours and tag (status_view.c). */
        s_ui.battery_low      = b.low ? true : false;
        s_ui.battery_critical = b.critical ? true : false;
        /* Critical-battery lockout: Tom already holds the speaker at gain 0
         * (Brendon told him); here it only changes what is drawn.
         * s_status_dirty rebuilds the header and footer; render() spots the
         * Volume screen notice (s_vol_locked_drawn) and the "(locked)" info
         * lines (s_disp) by itself. */
        s_ui.speaker_locked = b.lockout ? true : false;
        s_status_dirty = 1U;
    }

    StorageStatusMsg_t st;
    if (osMessageQueueGet(storageStatusQueue, &st, NULL, 0U) == osOK) {
        storage_status_in(&st);
    }

    StorageReply_t rep;
    if (s_replyQueue != NULL && osMessageQueueGet(s_replyQueue, &rep, NULL, 0U) == osOK) {
        if (rep.type == STORAGE_REQ_LIST_FILES || rep.type == STORAGE_REQ_FILE_NAMES) {
            window_reply(&rep);
        } else if (rep.type == STORAGE_REQ_STATUS) {
            /* The debug screen's Storage page asks once a second. Only the
             * four fields that page alone shows are taken. Jack answers a
             * request before the rest of his loop pass, so the
             * storageStatusQueue publish drained above can be NEWER (card
             * pulled, playback ended): the card, transport and status-text
             * fields stay with the publishes ("newest wins"), or an older
             * reply could leave a stale "SD: Ready" or playing == 1 behind. */
            s_sto.bus_width   = rep.status.bus_width;
            s_sto.last_result = rep.status.last_result;
            s_sto.total_kb    = rep.status.total_kb;
            s_sto.free_kb     = rep.status.free_kb;
        }
    }

    JackReply_t ack;
    uint8_t     refused = 0U;                  /* Jack refused a start: the pop-up, after the faults */
    if (s_jackReplyQueue != NULL && osMessageQueueGet(s_jackReplyQueue, &ack, NULL, 0U) == osOK) {
        refused = jack_ack_in(&ack);
    }

    /* Faults: all pending, timeout 0. Producers send each fault once per
     * occurrence, so whatever arrives here is new: it opens the modal
     * fault screen (or replaces the fault it shows). */
    FaultMsg_t f;
    while (osMessageQueueGet(faultQueue, &f, NULL, 0U) == osOK) {
        uint8_t code = (uint8_t)(f.code & (uint8_t)~FAULT_CODE_SIMULATED);
        if (f.source == FAULT_SRC_AUDIO && code == FAULT_AUDIO_FX_BUDGET) {
            continue;                              /* no longer produced (effects are made ahead): ignored */
        }
        if (ui_show_fault(&s_ui, f.source, f.code, f.line2, f.line3)) {
            s_fault_new = 1U;                      /* drawn straight after this drain (IR6) */
            s_hold_event = EVENT_NONE;             /* a held Volume +/- must not repeat behind it */
        }
    }

    /* A start Jack refused although the pre-check let it through (a file
     * that would not open, no status had come yet, he was still busy):
     * the pop-up says why, worded from the status he published just
     * before his ack. Opened after the faults: when he raised one for it
     * (Jack queues the fault before his ack), the fault screen is up and
     * says it already, and sdp_open() opens nothing over it. */
    if (refused) {
        sv_sd_in_t sd  = sd_in();
        uint8_t    rec = (ack.type == JACK_CMD_RECORD_START) ? 1U : 0U;
        popup_show(rec, sdp_refusal_reason(rec ? true : false, &sd, s_sto.file_count));
    }

    /* Debug screen: BrendonTask's 1 Hz power snapshot (newest wins), kept by
     * tony_debug.c even while the screen is closed. The header takes three
     * flags from it. */
    TonyDebug_DrainPower();
    power_flags_update();
}

/* -------------------------------------------------------------------------- */
/* Renderer (display_info_t + ui_state_t -> ILI9341 through tony_ports)        */
/* -------------------------------------------------------------------------- */
static const char *row_label(ui_screen_t screen, uint8_t i)
{
    if (screen == UI_SCREEN_EFFECTS) return ui_effect_name((ui_effect_t)(EFFECT_1 + i));
    /* "Insert SD card" while the slot is empty (render() redraws the row when it changes) */
    if (screen == UI_SCREEN_RECORD && i == 0U) return ui_record_start_label(&s_ui);
    /* "Sure? Tap again" while the Delete row is armed */
    if (screen == UI_SCREEN_FILE && i == FILE_DELETE_ROW) return dc_label(&s_dc);
    return s_layout[screen].rows[i];
}

/* The Home tiles in encoder order (s_layout's Home rows, handle_home()'s list). */
static const ui_screen_t s_home_items[6] = { UI_SCREEN_RECORD, UI_SCREEN_PLAY, UI_SCREEN_EFFECTS,
                                             UI_SCREEN_VOLUME, UI_SCREEN_FILE, UI_SCREEN_BATTERY };

/* The row drawn blue on st's screen (ROW_NONE: none): the Home or Effects
 * cursor, and on the other screens with rows the row last tapped there
 * (tapped; render() sets it back to ROW_NONE once that screen is left).
 * draw_row() colours the rows from this and active_row(), and render()
 * redraws just the rows whose answer changed, so the two always agree. */
static uint8_t blue_row(const ui_state_t *st, uint8_t tapped)
{
    switch (st->screen) {
        case UI_SCREEN_HOME:
            for (uint8_t i = 0U; i < 6U; i++) {
                if (s_home_items[i] == st->home_highlighted) return i;
            }
            return ROW_NONE;
        case UI_SCREEN_EFFECTS:
            return (st->effect_highlighted >= EFFECT_1 && st->effect_highlighted < EFFECT_COUNT)
                   ? (uint8_t)(st->effect_highlighted - EFFECT_1) : ROW_NONE;
        default:
            return tapped;
    }
}

/* The Effects row of the active effect, marked "* " and grey unless it is
 * also blue. ROW_NONE with no effect on, and on every other screen. */
static uint8_t active_row(const ui_state_t *st)
{
    return (st->screen == UI_SCREEN_EFFECTS && st->active_effect >= EFFECT_1 && st->active_effect < EFFECT_COUNT)
           ? (uint8_t)(st->active_effect - EFFECT_1) : ROW_NONE;
}

static void draw_row(ui_screen_t screen, uint8_t i)
{
    uint8_t hi = (blue_row(&s_ui, s_tapped_row) == i) ? 1U : 0U;
    if (screen == UI_SCREEN_HOME) {                  /* 3 x 2 tile, label centred */
        uint16_t x = HOME_CELL_X(i), y = HOME_CELL_Y(i);
        uint16_t col = hi ? BLUE : 0x2104U;
        const char *label = row_label(screen, i);
        ILI9341_Draw_Rectangle(x, y, HOME_CELL_W, HOME_CELL_H, col);
        ILI9341_Draw_Text(label, (uint16_t)(x + (HOME_CELL_W - strlen(label) * FONT_W * 2U) / 2U),
                          (uint16_t)(y + (HOME_CELL_H - 16U) / 2U), WHITE, 2, col);
        return;
    }
    uint16_t y = (uint16_t)(MENU_Y0 + i * MENU_GAP);
    uint8_t active = (active_row(&s_ui) == i) ? 1U : 0U;
    /* An armed Delete row is red, whatever else it is (armed > tapped > grey). */
    uint8_t armed = (screen == UI_SCREEN_FILE && i == FILE_DELETE_ROW && dc_armed(&s_dc)) ? 1U : 0U;
    uint16_t col = armed ? RED : (hi ? BLUE : (active ? DARKGREY : 0x2104U /* near black */));
    if (screen == UI_SCREEN_FILE && i == FILE_DELETE_ROW) s_dc_armed_drawn = armed;
    ILI9341_Draw_Rectangle(MENU_X, y, MENU_W, MENU_H, col);
    char label[24];
    snprintf(label, sizeof(label), "%s%s", active ? "* " : "", row_label(screen, i));
    ILI9341_Draw_Text(label, (uint16_t)(MENU_X + 8U), (uint16_t)(y + 8U), WHITE, 2, col);
}

/* s centred in a whole row of size-`size` characters, space-padded to the
 * full width (row: at least SCREEN_W / FONT_W + 1 bytes). */
static void centre_in_row(const char *s, uint8_t size, char *row)
{
    size_t width = SCREEN_W / (FONT_W * size);
    size_t len = strlen(s);
    if (len > width) len = width;
    memset(row, ' ', width);
    memcpy(&row[(width - len) / 2U], s, len);
    row[width] = '\0';
}

/* Where a centred row starts: x of its first character cell. */
static uint16_t row_x(uint8_t size)
{
    return (uint16_t)((SCREEN_W - (SCREEN_W / (FONT_W * size)) * FONT_W * size) / 2U);
}

/* Text centred across the full width, space-padded to the whole row so it
 * also erases whatever was drawn there before. */
static void draw_centred(const char *s, uint16_t y, uint16_t colour, uint8_t size)
{
    char row[SCREEN_W / FONT_W + 1U];
    centre_in_row(s, size, row);
    ILI9341_Draw_Text(row, row_x(size), y, colour, size, BLACK);
}

/* Draw text at (x, y) one character cell at a time, skipping the cells
 * where was, the text the panel shows there now (same length, same
 * colours), already has that letter. Each cell repaints its own
 * background, so the panel ends up exactly as after a whole draw. */
static void draw_changed_cells(const char *text, const char *was, uint16_t x, uint16_t y,
                               uint16_t colour, uint8_t size, uint16_t bg)
{
    for (size_t i = 0U; text[i] != '\0'; i++) {
        if (text[i] == was[i]) continue;
        ILI9341_Draw_Char(text[i], (uint16_t)(x + i * FONT_W * size), y, colour, size, bg);
    }
}

/* A centred line that is on the panel already as was, in the same colour
 * and size: only the characters that changed are drawn. A 5 % step of
 * "Preparing 45%" is one or two letters, about 4 ms instead of 35 ms for
 * the whole line. That matters: TonyTask draws at osPriorityLow on a
 * busy-waiting SPI, so every drawing millisecond is taken from
 * FxRenderTask, which is making the very file the user waits for. */
static void draw_centred_changes(const char *s, const char *was, uint16_t y, uint16_t colour, uint8_t size)
{
    char row[SCREEN_W / FONT_W + 1U];
    char row_was[SCREEN_W / FONT_W + 1U];
    centre_in_row(s, size, row);
    centre_in_row(was, size, row_was);
    draw_changed_cells(row, row_was, row_x(size), y, colour, size, BLACK);
}

/* One info line: the whole line after the body was cleared (was NULL),
 * else only the characters that changed. */
static void draw_info_line(const char *s, const char *was, uint16_t y, uint16_t colour, uint8_t size)
{
    if (was == NULL) {
        draw_centred(s, y, colour, size);
    } else {
        draw_centred_changes(s, was, y, colour, size);
    }
}

/* Info lines. force = 1 (after the body was cleared) draws every line;
 * otherwise only a line whose text differs from the last drawn one
 * (s_disp_drawn) is redrawn, so a value that changes every second, like the
 * Battery screen's current and time, never makes the other lines flicker.
 * render() calls this on every pass, so the same rule keeps the fault
 * screen still (once a second only the battery voltage in s_disp changes),
 * and a different fault replacing the one shown redraws just the lines
 * that differ. */
static void draw_info_lines(uint8_t force)
{
    if (s_ui.screen == UI_SCREEN_HOME) return;       /* the tiles fill the screen; no info lines */
    uint8_t rows = s_layout[s_ui.screen].row_count;
    uint8_t fault = (s_ui.screen == UI_SCREEN_FAULT) ? 1U : 0U;          /* FOUR_LINE_* layout */
    uint8_t battery = (s_ui.screen == UI_SCREEN_BATTERY) ? 1U : 0U;      /* BAT_LINE_* layout */
    uint8_t count = battery ? 6U : (fault ? 4U : 3U);
    const char *lines[6] = { s_disp.line1, s_disp.line2, s_disp.line3, s_disp.line4, s_disp.line5,
                             s_disp.line6 };
    const char *drawn[6] = { s_disp_drawn.line1, s_disp_drawn.line2, s_disp_drawn.line3, s_disp_drawn.line4,
                             s_disp_drawn.line5, s_disp_drawn.line6 };
    char extra[DISPLAY_LABEL_MAX];
    extra[0] = '\0';
    if (s_ui.screen == UI_SCREEN_FILE) {
        /* Line 3 shows the selected file name, which display_info_t does not
         * hold: it is compared with its own copy, s_file_line_drawn. (It was
         * redrawn whenever any line changed, so the name shimmered about
         * once a second with the battery voltage.) "> ..." while the window
         * around the selection is still on its way. */
        if (s_ui.file_count > 0U) {
            snprintf(extra, sizeof(extra), "> %s", sel_name_shown());
            lines[2] = extra;
        }
        drawn[2] = s_file_line_drawn;
    }
    for (uint8_t i = 0U; i < count; i++) {
        if (!force && strcmp(lines[i], drawn[i]) == 0) continue;   /* unchanged */
        const char *was = force ? NULL : drawn[i];                 /* NULL: draw the whole line */
        if (battery) {
            /* No rows on this screen: six big lines from under the
             * title: charge, current now, 2-minute average current,
             * voltage, time, status. */
            draw_info_line(lines[i], was, BAT_LINE_Y0 + i * BAT_LINE_DY, YELLOW, 2);
        } else if (fault) {
            /* Four big lines: source, what happened and what it means in
             * yellow, then "Press any key" in grey. */
            draw_info_line(lines[i], was, FOUR_LINE_Y0 + i * FOUR_LINE_DY, (i == 3U) ? LIGHTGREY : YELLOW, 2);
        } else if (rows <= 4U) {
            /* Free space below the rows: big and centred. */
            draw_info_line(lines[i], was, INFO_Y0 + i * INFO_DY, YELLOW, 2);
        } else {
            /* Six rows (Effects) fill the body down to y 261: small and
             * centred under them, two of the three lines: "Active: X" and
             * the hint. Line 2 ("Cursor: X") is left out, the blue row
             * already shows the cursor. A size-1 row is 40 characters, so
             * even "[OFF] Tap to activate" (21) shows whole. */
            if (i == 1U) continue;
            draw_info_line(lines[i], was, EFFECTS_INFO_Y0 + (i / 2U) * EFFECTS_INFO_DY, YELLOW, 1);
        }
    }
    if (s_ui.screen == UI_SCREEN_FILE) {
        strncpy(s_file_line_drawn, lines[2], sizeof(s_file_line_drawn) - 1U);
    }
}

/* Play screen: one outlined square in the centre showing what a tap does —
 * a right-pointing triangle (play / resume) or two bars (pause). Hit area in
 * touch_region.c (PLAY_BTN_* plus PLAY_HIT_PAD). */
static void draw_play_button(void)
{
    const uint16_t x = PLAY_BTN_X, y = PLAY_BTN_Y, w = PLAY_BTN_W, h = PLAY_BTN_H;
    const uint16_t t = 6U;                                   /* outline thickness */
    ILI9341_Draw_Rectangle(x, y, w, h, WHITE);
    ILI9341_Draw_Rectangle(x + t, y + t, w - 2U * t, h - 2U * t, BLACK);

    if (s_ui.playback == PLAYBACK_PLAYING) {                 /* pause: two bars */
        const uint16_t bw = w * 14U / 100U, in_x = w * 30U / 100U, in_y = h * 28U / 100U;
        ILI9341_Draw_Rectangle(x + in_x, y + in_y, bw, h - 2U * in_y, WHITE);
        ILI9341_Draw_Rectangle(x + w - in_x - bw, y + in_y, bw, h - 2U * in_y, WHITE);
    } else {                                                 /* play: triangle */
        const uint16_t tx = x + w * 36U / 100U, tw = w * 36U / 100U, th = h * 44U / 100U;
        const uint16_t cy = y + h / 2U;
        for (uint16_t i = 0U; i <= tw; i++) {                /* one column per pixel, narrowing to the tip */
            uint16_t half = (uint16_t)(((uint32_t)(th / 2U) * (tw - i)) / tw);
            ILI9341_Draw_Vertical_Line(tx + i, cy - half, 2U * half + 1U, WHITE);
        }
    }
}

/* Speaker: a square body and a cone widening to the right (one column per
 * pixel). s = scale; the icon is 14s wide and 22s tall, centred on cy. */
static void draw_speaker(uint16_t x, uint16_t cy, uint16_t s, uint16_t colour)
{
    ILI9341_Draw_Rectangle(x, cy - 4U * s, 6U * s, 8U * s + 1U, colour);
    for (uint16_t i = 0U; i <= 8U * s; i++) {
        uint16_t half = (uint16_t)(4U * s + (7U * i) / 8U);
        ILI9341_Draw_Vertical_Line(x + 6U * s + i, cy - half, 2U * half + 1U, colour);
    }
}

/* A thick X in a size x size box (mute), drawn as 4 x 4 blocks: 3 x 3 = 9
 * pixels is an odd burst, which left the red X full of blue specks. */
static void draw_cross(uint16_t x, uint16_t y, uint16_t size, uint16_t colour)
{
    for (uint16_t k = 0U; k + CROSS_BLOCK <= size; k++) {
        ILI9341_Draw_Rectangle(x + k, y + k, CROSS_BLOCK, CROSS_BLOCK, colour);
        ILI9341_Draw_Rectangle(x + k, y + size - CROSS_BLOCK - k, CROSS_BLOCK, CROSS_BLOCK, colour);
    }
}

/* 0..3 lit level bars: 0 at volume 0, 3 from 67 up. */
static uint8_t vol_level(void)
{
    uint8_t lv = (uint8_t)((s_ui.volume + 32U) / 33U);
    return (lv > 3U) ? 3U : lv;
}

/* Big icon above the buttons: speaker + three rising bars (lit = level),
 * or grey bars under a red X when muted. */
static void draw_volume_icon(void)
{
    const uint16_t bars_x = VOL_ICON_X + 34U;
    ILI9341_Draw_Rectangle(VOL_ICON_X, VOL_ICON_CY - 23U, 66U, 47U, BLACK);
    draw_speaker(VOL_ICON_X, VOL_ICON_CY, 2U, WHITE);
    for (uint8_t b = 0U; b < 3U; b++) {
        uint16_t h = (uint16_t)(14U * (b + 1U));
        uint16_t col = (!s_ui.muted && b < vol_level()) ? WHITE : DARKGREY;
        ILI9341_Draw_Rectangle(bars_x + b * 11U, VOL_ICON_CY - h / 2U, 6U, h, col);
    }
    if (s_ui.muted) draw_cross(bars_x, VOL_ICON_CY - 15U, 30U, RED);
    s_vol_level_drawn = vol_level();
}

/* [ - ] [ + ] [ speaker-X ]: - / + turn blue while pressed (and briefly
 * after a quick tap), mute is blue while muted. */
static uint8_t vol_pressed(void)
{
    ui_event_t held = s_hold_event;
    if (held == EVENT_NONE && (int32_t)(osKernelGetTickCount() - s_vol_flash_until) < 0) {
        held = (s_vol_pressed_drawn == 1U) ? EVENT_VOLUME_DOWN :
               (s_vol_pressed_drawn == 2U) ? EVENT_VOLUME_UP : EVENT_NONE;
    }
    return (held == EVENT_VOLUME_DOWN) ? 1U : (held == EVENT_VOLUME_UP) ? 2U : 0U;
}

static void draw_volume_buttons(void)
{
    uint8_t pressed = vol_pressed();
    for (uint8_t i = 0U; i < 3U; i++) {
        uint16_t x = VOL_BTN_X(i), cx = x + VOL_BTN_W / 2U, cy = VOL_BTN_Y + VOL_BTN_H / 2U;
        uint8_t  on = (i == 2U) ? (s_ui.muted ? 1U : 0U) : (pressed == i + 1U ? 1U : 0U);
        uint16_t bg = on ? BLUE : TILE_GREY;
        ILI9341_Draw_Rectangle(x, VOL_BTN_Y, VOL_BTN_W, VOL_BTN_H, bg);
        if (i < 2U) {
            ILI9341_Draw_Rectangle(cx - 16U, cy - 3U, 33U, 7U, WHITE);                 /* minus */
            if (i == 1U) ILI9341_Draw_Rectangle(cx - 3U, cy - 16U, 7U, 33U, WHITE);    /* plus  */
        } else {
            draw_speaker(cx - 17U, cy, 1U, WHITE);
            draw_cross(cx + 3U, cy - 7U, 15U, WHITE);
        }
    }
    s_vol_pressed_drawn = pressed;
}

/* Battery lockout: the speaker icon gives way to a red notice in the same
 * place (between the title and the buttons). The -/+/mute buttons stay and
 * keep working: Tom stores the values and uses them after the release. */
static void draw_volume_locked(void)
{
    ILI9341_Draw_Rectangle(VOL_ICON_X, VOL_ICON_CY - 23U, 66U, 47U, BLACK);   /* the icon's box */
    draw_centred("Locked: low battery", VOL_LOCK_TEXT_Y, RED, 2);
}

static void draw_volume_screen(uint8_t force)
{
    uint8_t muted  = s_ui.muted ? 1U : 0U;
    uint8_t locked = s_ui.speaker_locked ? 1U : 0U;
    uint8_t lock_changed = (locked != s_vol_locked_drawn) ? 1U : 0U;
    if (locked) {
        if (force || lock_changed) draw_volume_locked();
    } else {
        /* Just released: the notice is wider than the icon, erase its row. */
        if (lock_changed && !force) draw_centred("", VOL_LOCK_TEXT_Y, BLACK, 2);
        if (force || lock_changed || muted != s_vol_muted_drawn || vol_level() != s_vol_level_drawn) draw_volume_icon();
    }
    if (force || muted != s_vol_muted_drawn || vol_pressed() != s_vol_pressed_drawn) draw_volume_buttons();
    s_vol_muted_drawn  = muted;
    s_vol_locked_drawn = locked;
}

/* The record clock, one for the Record screen and the footer so they always
 * show the same time: ms recorded so far (0 until Jack's status or his
 * RECORD_START ack starts the clock, and whenever the UI is not
 * recording), at most REC_TOTAL_MS ... */
static uint32_t rec_elapsed_ms(void)
{
    uint32_t el = 0U;
    if (s_ui.playback == PLAYBACK_RECORDING && s_rec_timing) {
        el = osKernelGetTickCount() - s_rec_start_ms;
        if (el > REC_TOTAL_MS) el = REC_TOTAL_MS;
    }
    return el;
}

/* ... and the whole seconds left, rounded up (9.2 s left shows 0:10): 0 only
 * once time is up and Jack is saving the file. At most the record length,
 * which is asserted to fit (JACK_DEFAULT_RECORD_SECONDS < 255). */
static uint8_t rec_left_s(void)
{
    return (uint8_t)((REC_TOTAL_MS - rec_elapsed_ms() + 999U) / 1000U);
}

/* Record screen: time left as m:ss (grey "0:10" = the limit while idle, red
 * while recording, "Saving" once time is up until Jack finishes the file) and
 * a bar that fills as it goes. Only the parts that changed are redrawn. */
static void draw_rec_timer(uint8_t force)
{
    uint8_t  rec  = (s_ui.playback == PLAYBACK_RECORDING) ? 1U : 0U;
    uint32_t el   = rec_elapsed_ms();
    uint8_t  left = rec_left_s();

    char t[sizeof(s_rec_text_drawn)];
    if (left == 0U) {
        snprintf(t, sizeof(t), "Saving");
    } else {
        snprintf(t, sizeof(t), "%u:%02u", (unsigned)(left / 60U), (unsigned)(left % 60U));
    }
    if (force || strcmp(t, s_rec_text_drawn) != 0 || rec != s_rec_colour_drawn) {
        draw_centred(t, REC_TIMER_Y, rec ? RED : DARKGREY, 4);
        strncpy(s_rec_text_drawn, t, sizeof(s_rec_text_drawn) - 1U);
        s_rec_colour_drawn = rec;
    }

    uint16_t fill = (uint16_t)(((uint32_t)REC_BAR_W * el) / REC_TOTAL_MS);
    if (force || fill != s_rec_fill_drawn) {
        if (fill > 0U) ILI9341_Draw_Rectangle(REC_BAR_X, REC_BAR_Y, fill, REC_BAR_H, RED);
        if (fill < REC_BAR_W) ILI9341_Draw_Rectangle(REC_BAR_X + fill, REC_BAR_Y, REC_BAR_W - fill, REC_BAR_H, DARKGREY);
        s_rec_fill_drawn = fill;
    }
}

/* Play screen: the recording that is playing (Jack's status), or, when idle,
 * the one the button will start (the Files screen selection), "No
 * recordings" for an empty card and "Insert SD card" with none in the slot
 * (ui_play_idle_name). */
static const char *play_file_name(void)
{
    if (s_sto.playing && s_sto.current_name[0]) return s_sto.current_name;
    return ui_play_idle_name(&s_ui, sel_name_shown());
}

static void draw_play_name(void)
{
    const char *name = play_file_name();
    draw_centred(name, PLAY_NAME_Y, WHITE, 2);
    strncpy(s_play_name_drawn, name, sizeof(s_play_name_drawn) - 1U);
}

/* Dedicated HOME button, right end of the title bar of every screen but
 * Home and the fault screen, which a tap anywhere closes (touch target in
 * touch_region.c). */
static void draw_home_button(void)
{
    if (s_ui.screen == UI_SCREEN_HOME || s_ui.screen == UI_SCREEN_FAULT) return;
    ILI9341_Draw_Rectangle(HOME_BTN_X, HOME_BTN_Y, HOME_BTN_W, HOME_BTN_H, BLUE);
    ILI9341_Draw_Text("HOME", HOME_BTN_X + 12U, (uint16_t)(HOME_BTN_Y + 7U), WHITE, 2, BLUE);
}

/* No-SD pop-up: the white edge as four strips, the red inside, then the
 * three lines (sdp_line) centred in the box, white on red. Every pixel of
 * the box is painted, so new words simply replace the old ones. About
 * 40 ms for the box and 1.2 ms per letter. */
static void draw_popup(void)
{
    const uint16_t in_h = POPUP_H - 2U * POPUP_EDGE;
    ILI9341_Draw_Rectangle(POPUP_X, POPUP_Y, POPUP_W, POPUP_EDGE, WHITE);                           /* top    */
    ILI9341_Draw_Rectangle(POPUP_X, POPUP_Y + POPUP_H - POPUP_EDGE, POPUP_W, POPUP_EDGE, WHITE);    /* bottom */
    ILI9341_Draw_Rectangle(POPUP_X, POPUP_Y + POPUP_EDGE, POPUP_EDGE, in_h, WHITE);                 /* left   */
    ILI9341_Draw_Rectangle(POPUP_X + POPUP_W - POPUP_EDGE, POPUP_Y + POPUP_EDGE, POPUP_EDGE, in_h, WHITE);   /* right */
    ILI9341_Draw_Rectangle(POPUP_X + POPUP_EDGE, POPUP_Y + POPUP_EDGE, POPUP_W - 2U * POPUP_EDGE, in_h, RED);
    for (uint8_t i = 0U; i < SDP_LINES; i++) {
        const char *t   = sdp_line(s_popup.reason, s_popup.record, i);
        size_t      len = strlen(t);
        if (len == 0U || len > SDP_TEXT_W) continue;           /* sdp_line() keeps to SDP_TEXT_W */
        ILI9341_Draw_Text(t, (uint16_t)(POPUP_X + (POPUP_W - len * 2U * FONT_W) / 2U),
                          (uint16_t)(POPUP_TEXT_Y0 + i * POPUP_TEXT_DY), WHITE, 2, RED);
    }
    s_popup_drawn        = 1U;
    s_popup_drawn_reason = s_popup.reason;
    s_popup_drawn_rec    = s_popup.record ? 1U : 0U;
}

/* RGB565 of each status_view colour (sv_colour_t order). */
static const uint16_t s_sv_rgb[] = {
    [SV_BLACK]       = BLACK,
    [SV_WHITE]       = WHITE,
    [SV_LIGHTGREY]   = LIGHTGREY,
    [SV_DARKGREY]    = DARKGREY,
    [SV_RED]         = RED,
    [SV_ORANGE]      = ORANGE,
    [SV_YELLOW]      = YELLOW,
    [SV_GREENYELLOW] = GREENYELLOW,
    [SV_GREEN]       = GREEN,
    [SV_CYAN]        = CYAN,
    [SV_MAGENTA]     = MAGENTA,
};
_Static_assert(sizeof(s_sv_rgb) / sizeof(s_sv_rgb[0]) == (size_t)SV_COLOUR_COUNT,
               "one RGB565 value for every sv_colour_t");

static uint16_t sv_rgb(sv_colour_t c)
{
    return ((unsigned)c < (unsigned)SV_COLOUR_COUNT) ? s_sv_rgb[c] : WHITE;
}

/* Power header, y 0..HEADER_H-1 on every screen but Debug: the tag, the
 * battery icon with the SoC beside it, TO EMPTY and TO FULL. force = 1 right
 * after the whole panel was cleared: every part, with the labels and the
 * rule, which never change. Otherwise only what differs from the last draw
 * (s_hdr_drawn) is sent: a battery message that changes nothing costs no
 * SPI time at all, a new SoC about 5 ms, a new time about 7 ms. Each text
 * has a fixed width and every character paints its own background, so
 * nothing is blanked first (no blink). The outline is redrawn only when
 * the colour changes, the fill when its width or the colour does. */
static void draw_header(uint8_t force)
{
    const sv_header_t *h = &s_hdr_now, *was = &s_hdr_drawn;
    sv_build_header(&s_ui, &s_hdr_now);
    uint16_t level = sv_rgb(h->level_colour);           /* SoC text, outline and fill */
    uint8_t  level_changed = (h->level_colour != was->level_colour) ? 1U : 0U;

    if (force) {
        ILI9341_Draw_Text("TO EMPTY", HDR_TTE_LABEL_X, HDR_TEXT_Y, LIGHTGREY, 1, BLACK);
        ILI9341_Draw_Text("TO FULL", HDR_TTF_LABEL_X, HDR_TEXT_Y, LIGHTGREY, 1, BLACK);
        ILI9341_Draw_Rectangle(0, HDR_RULE_Y, SCREEN_W, HDR_LINE, DARKGREY);
    }
    if (force || h->tag_colour != was->tag_colour || strcmp(h->tag, was->tag) != 0) {
        ILI9341_Draw_Text(h->tag, HDR_TAG_X, HDR_TEXT_Y, sv_rgb(h->tag_colour), 1, BLACK);
    }
    if (force || level_changed) {
        ILI9341_Draw_Rectangle(HDR_ICON_X, HDR_VALUE_Y, HDR_ICON_W, HDR_LINE, level);              /* top    */
        ILI9341_Draw_Rectangle(HDR_ICON_X, HDR_VALUE_Y + HDR_ICON_H - HDR_LINE, HDR_ICON_W, HDR_LINE,
                               level);                                                             /* bottom */
        ILI9341_Draw_Rectangle(HDR_ICON_X, HDR_FILL_Y, HDR_LINE, HDR_FILL_H, level);               /* left   */
        ILI9341_Draw_Rectangle(HDR_ICON_X + HDR_ICON_W - HDR_LINE, HDR_FILL_Y, HDR_LINE, HDR_FILL_H,
                               level);                                                             /* right  */
    }
    if (force || h->nub_colour != was->nub_colour) {
        ILI9341_Draw_Rectangle(HDR_NUB_X, HDR_NUB_Y, HDR_NUB_W, HDR_NUB_H, sv_rgb(h->nub_colour));
    }
    if (force || level_changed || h->fill_px != was->fill_px) {
        if (h->fill_px > 0U) ILI9341_Draw_Rectangle(HDR_FILL_X, HDR_FILL_Y, h->fill_px, HDR_FILL_H, level);
        if (h->fill_px < SV_FILL_MAX) {
            ILI9341_Draw_Rectangle(HDR_FILL_X + h->fill_px, HDR_FILL_Y, SV_FILL_MAX - h->fill_px, HDR_FILL_H, BLACK);
        }
    }
    if (force || level_changed || strcmp(h->soc, was->soc) != 0) {
        ILI9341_Draw_Text(h->soc, HDR_SOC_X, HDR_VALUE_Y, level, 2, BLACK);
    }
    if (force || h->tte_colour != was->tte_colour || strcmp(h->tte, was->tte) != 0) {
        ILI9341_Draw_Text(h->tte, HDR_TTE_X, HDR_VALUE_Y, sv_rgb(h->tte_colour), 2, BLACK);
    }
    if (force || h->ttf_colour != was->ttf_colour || strcmp(h->ttf, was->ttf) != 0) {
        ILI9341_Draw_Text(h->ttf, HDR_TTF_X, HDR_VALUE_Y, sv_rgb(h->ttf_colour), 2, BLACK);
    }
    s_hdr_drawn = s_hdr_now;
}

/* The SD chip's letters, centred in its box to the pixel: x 4 for seven
 * letters, 10 for six, 16 for five. sv_sd_chip() pads the text to seven
 * columns, centred only to the column, which left a six-letter text (SD USB,
 * SD ERR, SD ...) 6 px left of centre, so the padding is dropped here. */
static void draw_chip_text(const sv_chip_t *chip)
{
    char        t[SV_CHIP_W + 1U];
    const char *p = chip->text;
    size_t      len = strlen(p);

    while (len > 0U && p[0] == ' ') { p++; len--; }
    while (len > 0U && p[len - 1U] == ' ') len--;
    memcpy(t, p, len);
    t[len] = '\0';
    ILI9341_Draw_Text(t, (uint16_t)(FTR_CHIP_X + (FTR_CHIP_W - len * 2U * FONT_W) / 2U), FTR_CHIP_TEXT_Y,
                      sv_rgb(chip->fg), 2, sv_rgb(chip->bg));
}

/* Footer, y STATUS_BAR_Y..319 on every screen but Debug: the SD chip, what
 * is recording or playing (the Record screen's clock), the effect and MUTE.
 * Same rules as the header: everything when force, otherwise only the
 * fields that changed. The chip box is redrawn when its colour or its text
 * changes (about 3 ms): the centred letters paint the box colour only
 * behind themselves, so a shorter text would leave the ends of a longer
 * one. */
static void draw_footer(uint8_t force)
{
    const sv_footer_t *f = &s_ftr_now, *was = &s_ftr_drawn;
    const sv_sd_in_t sd = sd_in();
    /* Line 1: Jack's answer while it lasts, worded from the same status as
     * the chip, so the two always agree. */
    sv_notice_t n;
    const char *notice = NULL;
    bool        notice_info = false;
    if (s_notice_on) {
        sv_answer_notice(s_notice_cmd, s_notice_ok ? true : false, s_notice_detail, &sd, s_sto.file_count,
                         s_notice_name, &n);
        notice      = n.text;
        notice_info = n.info;
    }
    sv_build_footer(&s_ui, &sd, rec_left_s(), notice, notice_info, &s_ftr_now);
    uint8_t box = (force || f->chip.bg != was->chip.bg || strcmp(f->chip.text, was->chip.text) != 0) ? 1U : 0U;

    if (force) ILI9341_Draw_Rectangle(0, STATUS_BAR_Y, SCREEN_W, HDR_LINE, DARKGREY);
    if (box) ILI9341_Draw_Rectangle(FTR_CHIP_X, FTR_CHIP_Y, FTR_CHIP_W, FTR_CHIP_H, sv_rgb(f->chip.bg));
    if (box || f->chip.fg != was->chip.fg) draw_chip_text(&f->chip);
    /* Line 1 and the FX field have a fixed width: in the same colour only
     * the characters that changed are drawn ("FX ECHO 45%" -> "50%"). */
    if (force || f->line1_colour != was->line1_colour) {
        ILI9341_Draw_Text(f->line1, FTR_TEXT_X, FTR_LINE1_Y, sv_rgb(f->line1_colour), 1, BLACK);
    } else if (strcmp(f->line1, was->line1) != 0) {
        draw_changed_cells(f->line1, was->line1, FTR_TEXT_X, FTR_LINE1_Y, sv_rgb(f->line1_colour), 1U, BLACK);
    }
    if (force || f->fx_colour != was->fx_colour) {
        ILI9341_Draw_Text(f->fx, FTR_TEXT_X, FTR_LINE2_Y, sv_rgb(f->fx_colour), 1, BLACK);
    } else if (strcmp(f->fx, was->fx) != 0) {
        draw_changed_cells(f->fx, was->fx, FTR_TEXT_X, FTR_LINE2_Y, sv_rgb(f->fx_colour), 1U, BLACK);
    }
    if (force || f->mute_colour != was->mute_colour || strcmp(f->mute, was->mute) != 0) {
        ILI9341_Draw_Text(f->mute, FTR_MUTE_X, FTR_LINE2_Y, sv_rgb(f->mute_colour), 1, BLACK);
    }
    s_ftr_drawn = s_ftr_now;
}

/* The saver's rectangles for this pass (screen_saver.c decides which),
 * painted with the driver's block fill. The 40 rects live on TonyTask's
 * stack only while they are painted. */
static void saver_paint_frame(uint32_t now)
{
    ss_rect_t rects[SS_MAX_RECTS];
    uint8_t   n = ss_frame(&s_saver, now, rects, SS_MAX_RECTS);
    for (uint8_t i = 0U; i < n; i++) {
        ILI9341_Draw_Rectangle(rects[i].x, rects[i].y, rects[i].w, rects[i].h, rects[i].colour);
    }
}

/* The SD BUSY tag in the saver's top-left corner while Jack writes effect
 * files (fx_busy): the "do not pull the card" warning must stay in view.
 * The whole face's skin covers it, so after that it is painted again; when
 * the writing stops, skin goes over it. No animation step paints there,
 * so it is never drawn again in between. Painting it takes about 8 ms
 * in the Debug build (the driver draws size-1 text one pixel at a time);
 * covering it with skin takes about 1.5 ms. */
static void saver_tag_update(bool whole_face_painted)
{
    ss_rect_t tag;
    uint8_t   busy = s_sto.fx_busy ? 1U : 0U;

    if (whole_face_painted) s_saver_tag_drawn = 0U;
    if (busy == s_saver_tag_drawn) return;
    ss_tag_rect(&tag);
    if (busy) {
        ILI9341_Draw_Rectangle(tag.x, tag.y, tag.w, tag.h, tag.colour);
        ILI9341_Draw_Text("SD BUSY", (uint16_t)(tag.x + (tag.w - 7U * FONT_W) / 2U),
                          (uint16_t)(tag.y + (tag.h - 8U) / 2U), BLACK, 1, tag.colour);
    } else {
        ILI9341_Draw_Rectangle(tag.x, tag.y, tag.w, tag.h, SS_RGB_SKIN);
    }
    s_saver_tag_drawn = busy;
}

/* The screen saver, at the top of every render(): it opens after
 * SS_IDLE_MS without input, and closes at once when it may not show (a
 * fault or the pop-up has come, recording, preparing). While it shows it
 * covers the whole panel the Debug screen's way: nothing else is drawn,
 * and once it closes s_chrome_valid = 0 has the screen under it drawn
 * whole again. Returns 1 while it shows. */
static uint8_t saver_render(void)
{
    uint32_t now       = osKernelGetTickCount();
    bool     recording = (s_ui.playback == PLAYBACK_RECORDING) || s_sto.recording;
    bool     preparing = ui_is_preparing(&s_ui) || (s_sto.playing == JACK_PLAY_PREPARING);
    bool     allowed   = ss_allowed(s_ui.screen, s_popup.open, recording, preparing);

    if (ss_update(&s_saver, now, allowed)) {
        dc_cancel(&s_dc);                       /* an armed Delete does not outlive the frog */
    }
    if (!ss_showing(&s_saver)) return 0U;
    bool whole = ss_opening(&s_saver);
    saver_paint_frame(now);
    saver_tag_update(whole);
    s_chrome_valid = 0U;                        /* the header and footer are gone from the panel */
    s_popup_drawn  = 0U;
    s_ui_drawn     = s_ui;
    s_disp_drawn   = s_disp;
    return 1U;
}

/* Called on every loop pass, but it sends the panel only what changed.
 * Why: drawing is slow. SPI1 runs at 9 MHz and, with no SPI interrupt in
 * this .ioc, the CPU waits for every byte; clearing the whole panel takes
 * about 0.14 s. While TonyTask draws it scans no input, and FxRenderTask,
 * the one task below it, gets no CPU time. So the panel's content is
 * remembered (s_ui_drawn, s_disp_drawn, s_hdr_drawn, s_ftr_drawn) and
 * compared: a whole screen only after a screen change (or once the
 * pop-up, the debug screen or the saver has covered it), otherwise only
 * the rows, lines and fields that differ. Order below: the screen saver or
 * the debug screen (each covers the whole panel), a whole screen, else
 * the partial redraws, then the header and footer. */
static void render(void)
{
    ui_get_display_info(&s_ui, &s_disp);
    /* Delete: off the File screen (also under a fault) it disarms; armed,
     * it disarms by itself after DC_CONFIRM_MS, and until then info line
     * 2 asks "Delete REC05.WAV?" instead of "SD OK" (the partial redraw
     * below draws only the characters that differ). */
    if (s_ui.screen != UI_SCREEN_FILE) dc_cancel(&s_dc);
    (void)dc_update(&s_dc, osKernelGetTickCount());
    if (s_ui.screen == UI_SCREEN_FILE && dc_armed(&s_dc)) {
        dc_prompt(sel_name_shown(), s_disp.line2, sizeof(s_disp.line2));
    }
    if (s_ui.playback != PLAYBACK_RECORDING) s_rec_timing = 0U;      /* finished, stopped or refused */
    if (s_tapped_screen != s_ui.screen) s_tapped_row = ROW_NONE;   /* left that screen: no stale blue */
    /* A footer notice has had its SV_NOTICE_MS: the footer is rebuilt
     * without it. Checked on every pass, also on Debug, so it ends on time
     * and is dropped for good (sv_notice_active flips back after 2^31 ms). */
    if (s_notice_on && !sv_notice_active(osKernelGetTickCount(), s_notice_until)) {
        s_notice_on = 0U;
        s_status_dirty = 1U;
    }
    /* The pop-up has had its SDP_SHOW_MS, or the screen it covered has
     * gone (a fault, Debug): it closes, and the screen under it is drawn
     * again below. (An input has closed it already in Tony_TaskEntry.) */
    (void)sdp_update(&s_popup, s_ui.screen, osKernelGetTickCount());
    if (saver_render()) return;                 /* the frog covers everything */

    if (s_ui.screen == UI_SCREEN_DEBUG) {
        /* The hidden debug screen draws itself in small text (tony_debug.c)
         * over the whole panel, without the title, HOME button, header and
         * footer. All of it when it opens or comes back from a fault
         * overlay; after that only the rows that changed. The header and
         * footer are gone from the panel now, so the screen after it (Home,
         * or a fault over it) clears and draws the whole panel. */
        TonyDebug_Render(&s_ui, &s_sto,
                         (s_screen_dirty || s_ui_drawn.screen != UI_SCREEN_DEBUG) ? 1U : 0U);
        s_chrome_valid = 0U;
        s_screen_dirty = 0U;
        s_popup_drawn = 0U;                                         /* the page covers the whole panel */
        s_ui_drawn = s_ui;
        s_disp_drawn = s_disp;
        return;
    }

    /* A pop-up on the panel that has closed: the screen under it is drawn
     * again, the same way as after a screen change. */
    uint8_t popup_gone = (s_popup_drawn && !s_popup.open) ? 1U : 0U;
    if (!s_chrome_valid || s_screen_dirty || popup_gone || s_ui_drawn.screen != s_ui.screen) {
        uint8_t whole = s_chrome_valid ? 0U : 1U;
        s_tapped_row_drawn = s_tapped_row;
        if (whole) {
            /* Boot, back from Debug, or a fault over Debug: the whole panel.
             * Draw_Rectangle's window is exact; ILI9341_Fill_Screen's is one
             * pixel too large and may leave the bottom rows (318-319) as they
             * were. */
            ILI9341_Draw_Rectangle(0, 0, SCREEN_W, SCREEN_H, BLACK);
        } else {
            /* A screen change, or the pop-up gone: only the title bar and
             * body (y 34..293, ~110 ms instead of ~140 ms). The header and
             * footer show the same on every screen and stay. */
            ILI9341_Draw_Rectangle(0, HEADER_H, SCREEN_W, STATUS_BAR_Y - HEADER_H, BLACK);
        }
        ILI9341_Draw_Text(s_layout[s_ui.screen].title, 20, TITLE_Y,
                          (s_ui.screen == UI_SCREEN_FAULT) ? RED : WHITE, 2, BLACK);
        draw_home_button();
        if (s_ui.screen == UI_SCREEN_PLAY) { draw_play_button(); draw_play_name(); }
        if (s_ui.screen == UI_SCREEN_RECORD) draw_rec_timer(1U);
        if (s_ui.screen == UI_SCREEN_VOLUME) draw_volume_screen(1U);
        for (uint8_t i = 0U; i < s_layout[s_ui.screen].row_count; i++) draw_row(s_ui.screen, i);
        draw_info_lines(1U);
        /* The body clear has erased the pop-up: one still open goes back
         * on top of the screen. */
        s_popup_drawn = 0U;
        if (s_popup.open) draw_popup();
        /* The frame last, so a fault over Debug has its text on the panel
         * before the ~80 ms of header and footer. */
        draw_header(whole);
        draw_footer(whole);
        s_chrome_valid = 1U;
        s_screen_dirty = 0U;
        s_status_dirty = 0U;
        s_ui_drawn = s_ui;
        s_disp_drawn = s_disp;
        return;
    }

    if (s_popup.open) {
        /* The pop-up covers the body. Nothing under it is drawn until it
         * closes, and then the whole body is (above), so the parts it
         * leaves in view wait at most SDP_SHOW_MS. New words (another
         * refusal while it shows) draw it again. */
        if (!s_popup_drawn || s_popup_drawn_reason != s_popup.reason ||
            s_popup_drawn_rec != (s_popup.record ? 1U : 0U)) {
            draw_popup();
        }
    } else {
        /* Partial redraws. Rows: a cursor step on Home or Effects, a new
         * active effect or a tapped row changes the look of at most four
         * rows (the old and new blue row, the old and new "* " row), so only
         * those are drawn again: one encoder detent is two tiles or rows,
         * ~48 ms, not all six (~144 ms). The Record screen's start row is
         * also drawn again when the card comes or goes ("Insert SD card"). */
        uint8_t changed = ui_rows_changed(blue_row(&s_ui_drawn, s_tapped_row_drawn), blue_row(&s_ui, s_tapped_row),
                                          active_row(&s_ui_drawn), active_row(&s_ui));
        if (s_ui.screen == UI_SCREEN_RECORD &&
            strcmp(ui_record_start_label(&s_ui), ui_record_start_label(&s_ui_drawn)) != 0) {
            changed |= 0x01U;
        }
        /* The Delete row armed or disarmed: red and "Sure? Tap again", or
         * back to "Delete". */
        if (s_ui.screen == UI_SCREEN_FILE && (dc_armed(&s_dc) ? 1U : 0U) != s_dc_armed_drawn) {
            changed |= (uint8_t)(1U << FILE_DELETE_ROW);
        }
        for (uint8_t i = 0U; i < s_layout[s_ui.screen].row_count; i++) {
            if ((changed & (1U << i)) != 0U) draw_row(s_ui.screen, i);
        }
        s_tapped_row_drawn = s_tapped_row;
        if (s_ui.screen == UI_SCREEN_PLAY && s_ui_drawn.playback != s_ui.playback) draw_play_button();
        if (s_ui.screen == UI_SCREEN_RECORD) draw_rec_timer(0U);
        if (s_ui.screen == UI_SCREEN_VOLUME) draw_volume_screen(0U);
        if (s_ui.screen == UI_SCREEN_PLAY &&
            strncmp(play_file_name(), s_play_name_drawn, sizeof(s_play_name_drawn)) != 0) {
            draw_play_name();
        }
        /* Info lines: only those whose text changed are drawn again (on the
         * Battery screen: charge, mV, the two currents, time, charging,
         * lockout; on the File screen also the name, which a new file list
         * can change alone). */
        draw_info_lines(0U);
    }
    /* Header and footer: rebuilt when a battery, power or storage message
     * has changed something (s_status_dirty, also set when a notice starts
     * or ends), when the effect, its Preparing percent or n/a, mute,
     * lockout or transport has changed here, and on every pass while
     * recording (the countdown). Only fields whose text or colour changed
     * reach the panel, so most of these cost no SPI time. */
    if (s_status_dirty || s_ui.playback == PLAYBACK_RECORDING || s_ui_drawn.playback != s_ui.playback ||
        s_ui_drawn.muted != s_ui.muted || s_ui_drawn.active_effect != s_ui.active_effect ||
        s_ui_drawn.prep_pct != s_ui.prep_pct || s_ui_drawn.fx_na != s_ui.fx_na ||
        s_ui_drawn.speaker_locked != s_ui.speaker_locked) {
        draw_header(0U);
        draw_footer(0U);
        s_status_dirty = 0U;
    }
    s_ui_drawn = s_ui;
    s_disp_drawn = s_disp;
}

/* -------------------------------------------------------------------------- */
/* Loop helpers: "n/a" and the input guard                                     */
/* -------------------------------------------------------------------------- */
/* "n/a": the original plays although an effect is selected (this file
 * cannot have effects, the effect engine is stalled, or a file just made
 * failed its check). Only once Jack's status describes him after Tony's
 * newest command (cmd_seq), which hides the few milliseconds between an
 * effect change and his answer. Once per pass: the effect and the command
 * number change in the event loop, the status in drain_queues(). */
static void fx_na_update(void)
{
    s_ui.fx_na = (s_sto.playing == JACK_PLAY_PLAYING && s_sto.cmd_seq == s_cmd_seq &&
                  s_sto.play_effect != (uint8_t)s_ui.active_effect) ? true : false;
}

/* Input guard around the fault screen. Drawing it, and drawing the screen
 * under it again once it closes, each blocks this task for ~0.2-0.3 s with
 * no input scan, while TIM3 keeps counting detents and a press or tap can
 * start. All of that belongs to a gesture made before the user could see the
 * new screen: a turn already under way must not close a fault unread (each
 * fault is sent only once), and the rest of the turn or tap that closed it
 * must not act on the screen underneath. So, called right after either
 * redraw: the whole detents counted so far are dropped and inputs are
 * ignored for FAULT_INPUT_GUARD_MS. A part-turned detent stays in the count
 * so the baseline keeps to the knob's click positions: taking the raw count
 * in the middle of a click would make every later click fire half-way and
 * lose the first click after each change of direction. */
static void input_guard_start(void)
{
    int16_t d = (int16_t)((uint16_t)__HAL_TIM_GET_COUNTER(s_htim_enc) - s_enc_last);
    s_enc_last = (uint16_t)(s_enc_last + (d / ENC_COUNTS_PER_DETENT) * ENC_COUNTS_PER_DETENT);
    s_hold_event = EVENT_NONE;
    s_input_guard = 1U;
    s_input_guard_until = osKernelGetTickCount() + FAULT_INPUT_GUARD_MS;
}

/* -------------------------------------------------------------------------- */
/* Public API                                                                  */
/* -------------------------------------------------------------------------- */
void Tony_Init(SPI_HandleTypeDef *hspi, ADC_HandleTypeDef *hadc, TIM_HandleTypeDef *htim_enc)
{
    TonyPorts_Init(hspi, hadc);
    ILI9341_Init();                       /* pre-kernel; HAL_Delay inside is fine here */
    /* vertical-ui: portrait. The driver's init ends in landscape
     * (SCREEN_HORIZONTAL_1); this replaces it with THE rotation of
     * ui_types.h, the one touch_tap() maps the touch with. Also pre-kernel,
     * so its HAL_Delay(1) is fine too. */
    ILI9341_Set_Rotation((uint8_t)UI_PORTRAIT_ROTATION);

    ui_init(&s_ui);
    s_prev = s_ui;
    s_htim_enc = htim_enc;
    (void)HAL_TIM_Encoder_Start(s_htim_enc, TIM_CHANNEL_ALL);
    s_enc_last = (uint16_t)__HAL_TIM_GET_COUNTER(s_htim_enc);   /* knob at rest: no phantom step */
    s_enc_seen = s_enc_last;              /* ... and no phantom input for the screen saver */
    memset(&s_sto, 0, sizeof(s_sto));
    strncpy(s_sto.status_text, "...", sizeof(s_sto.status_text) - 1U);
    s_sto_seen = 0U;                      /* SD chip "SD ..." until Jack's first status */
    fw_init(&s_win);                      /* no file list yet: the first one selects the last file */
    dc_init(&s_dc);                       /* the Delete row starts unarmed */

    /* Prime button edge state so a button held at boot does not trigger. */
    s_btn_prev[BTN_PA8] = button_pressed(GPIOA, GPIO_PIN_8);
    s_btn_prev[BTN_PB0] = button_pressed(GPIOB, GPIO_PIN_0);
    s_btn_prev[BTN_PB1] = button_pressed(GPIOB, GPIO_PIN_1);
    s_btn_prev[BTN_PB2] = button_pressed(GPIOB, GPIO_PIN_2);
    touch_filter_init(&s_touch);
    debug_hold_init(&s_debug_hold);
    sdp_init(&s_popup);
    if (s_btn_prev[BTN_PB0]) {
        /* BACK held through power-on: that press must not open the hidden
         * debug screen 2 s later either. Marked as already fired, so only
         * a release and a new 2 s hold open it. */
        s_debug_hold.down  = 1U;
        s_debug_hold.fired = 1U;
    }

    ILI9341_Fill_Screen(BLACK);
    ILI9341_Draw_Text("BJT2 SOUND TOY", (SCREEN_W - 14U * 2U * FONT_W) / 2U, SPLASH_Y,
                      WHITE, 2, BLACK);                                  /* x 36..203, y 140..155 */
    ILI9341_Draw_Text("starting...", (SCREEN_W - 11U * FONT_W) / 2U, SPLASH_Y + 30U,
                      LIGHTGREY, 1, BLACK);                              /* x 87..152, y 170..177 */
    s_screen_dirty = 1U;
    s_chrome_valid = 0U;                  /* the first frame clears and draws the whole panel */
}

void Tony_TaskEntry(void *argument)
{
    (void)argument;
    /* slide 24. Two slots (~0.26 KB more RTOS heap than one): the debug
     * Storage page's STATUS reply shares this queue with the File / Play
     * screens' file lists, and Jack puts with timeout 0, so with one slot a
     * STATUS reply still on its way when a file list is asked for would make
     * Jack drop the file list. At most one STATUS is ever outstanding. */
    const osMessageQueueAttr_t ra = { .name = "tonyReply" };
    s_replyQueue = osMessageQueueNew(2U, sizeof(StorageReply_t), &ra);
    const osMessageQueueAttr_t ja = { .name = "tonyJackAck" };
    s_jackReplyQueue = osMessageQueueNew(1U, sizeof(JackReply_t), &ja);

    /* Tell Tom the UI's initial volume and mute so both sides agree. */
    send_tom(TOM_CMD_SET_VOLUME, s_ui.volume);
    send_tom(TOM_CMD_SET_MUTE, s_ui.muted ? 1U : 0U);
    ss_init(&s_saver, osKernelGetTickCount());   /* untouched, the frog comes 30 s after boot */

    /* The loop, one pass about every 10 ms (lecture 07 slide 13's
     * "ButtonTask" shape: read the inputs, act, sleep):
     *   1. drain_queues()   what the other tasks sent (never waits)
     *   2. a new fault      drawn at once (PD2 IR6), then the input guard
     *   3. scan_inputs()    buttons, encoder, touch -> up to 4 events
     *   4. each event       ui_process_event(), then emit_commands()
     *   5. window_service(), fx_na_update(), the debug page's STATUS request
     *   6. render()         draw what changed
     *   7. osDelay(10)      sleep
     * Why poll every 10 ms: the buttons and the touch panel raise no
     * interrupt, so the task must look at them often. 10 ms is quick enough
     * to catch a normal press, and the task still sleeps most of the time,
     * which leaves the CPU to FxRenderTask below it (it makes the effect
     * files). The knob needs no fast polling: TIM3 counts it in hardware. */
    for (;;) {
        drain_queues();
        /* A fault overlay that has just opened over the debug screen's
         * Speaker page stops its test pattern before it is drawn. */
        TonyDebug_Update(&s_ui, &s_sto);
        if (s_fault_new) {
            /* A new fault: draw it now, before the touch scan (PD2 IR6,
             * visible within 500 ms). The header and footer stay, so it is
             * the title bar + body clear, title and 4 lines: roughly
             * 110 + 5 + 80 ms, about 0.2 s, on the 9 MHz SPI1. Over the
             * debug screen the whole panel is cleared and the header and
             * footer are drawn after the fault text: about 0.3 s.
             * Why here, before scan_inputs(): any event closes the fault
             * screen, so an input read in this same pass would close it
             * before it was ever on the panel. */
            render();
            s_fault_new = 0U;
            input_guard_start();     /* a turn or press already under way must not close it unread */
        }

        ui_event_t ev[4];
        uint8_t n = scan_inputs(ev, 4U);
        /* Screen saver: every input starts its 30 s again. The input that
         * wakes it does nothing else: render() below draws the screen under
         * it whole, then the input guard drops the rest of that touch,
         * press or turn. */
        uint8_t saver_woke = 0U;
        if (s_input_seen && ss_input(&s_saver, osKernelGetTickCount())) {
            n = 0U;
            s_hold_event = EVENT_NONE;
            s_tapped_row = ROW_NONE;
            saver_woke   = 1U;
        }
        if (s_input_guard) {
            if ((int32_t)(osKernelGetTickCount() - s_input_guard_until) < 0) {
                /* The fault screen, or the screen under it, has only just
                 * been drawn: this is still the turn / press / tap from
                 * before. The scan above kept the button and touch edge
                 * state up to date and took the detents off; its events
                 * are dropped. */
                n = 0U;
                s_hold_event = EVENT_NONE;
                s_tapped_row = ROW_NONE;
            } else {
                s_input_guard = 0U;
            }
        }
        uint8_t fault_closed = 0U;
        for (uint8_t i = 0U; i < n; i++) {
            ui_screen_t screen_before = s_ui.screen;
            /* Any input closes the pop-up and then does what it always
             * does: REC again once a card is in records (render() draws
             * the screen under the pop-up again). */
            (void)sdp_close_on_input(&s_popup);
            ui_process_event(&s_ui, ev[i]);
            sel_follow();                   /* a knob step on the File screen: the new name at once */

            /* Delete: a tap on the File screen's Delete row arms it or, the
             * second time, deletes; every other input disarms it. */
            if (ev[i] == EVENT_FILE_DELETE && screen_before == UI_SCREEN_FILE) {
                delete_row_pressed();
            } else {
                dc_cancel(&s_dc);
            }

            if (screen_before == UI_SCREEN_FAULT) {
                /* The event only closed the fault screen (the state machine
                 * changed nothing else, so there is no command to send).
                 * Drop the rest of this scan; the input guard starts once
                 * the screen underneath is back on the panel (below). */
                s_hold_event = EVENT_NONE;
                s_tapped_row = ROW_NONE;
                s_prev = s_ui;
                fault_closed = 1U;
                break;
            }

            if (screen_before == UI_SCREEN_DEBUG) {
                /* Debug screen: the state machine has only moved the cursor
                 * or gone Home, so emit_commands() below finds nothing to
                 * send. Push / PLAY / REC are the page's own actions. */
                TonyDebug_OnEvent(ev[i], &s_ui, &s_sto);
            }

            /* FILE_SELECT is UI-local in the state machine; here it starts the
             * selected recording (Appendix C) and shows the Play screen. A file
             * already looping is stopped first, so picking another switches.
             * Touching a row or pushing the encoder (PA8 = EVENT_MUTE_TOGGLE,
             * which the state machine treats as "select" on the File screen,
             * test G_btn_10) plays the selected file — but only a push made
             * ON the File screen: the same push on Home with "File"
             * highlighted is what opens the File screen, and must show the
             * list rather than start the last file. With no recording
             * listed there is nothing to select, but the press still says
             * why, as PLAY does (no card, no recordings, card on a PC);
             * when the card looks fine it does nothing. */
            if ((ev[i] == EVENT_FILE_SELECT || ev[i] == EVENT_MUTE_TOGGLE) &&
                screen_before == UI_SCREEN_FILE && s_ui.screen == UI_SCREEN_FILE &&
                s_ui.playback != PLAYBACK_RECORDING) {
                if (s_ui.file_count > 0U) {
                    if (s_ui.playback != PLAYBACK_IDLE) {
                        send_jack(JACK_CMD_PLAY_STOP);
                        s_prev.playback = PLAYBACK_IDLE;      /* the diff below sends PLAY_START */
                    }
                    s_ui.screen = UI_SCREEN_PLAY;
                    s_ui.playback = PLAYBACK_PLAYING;   /* the diff below sends PLAY_START(s_sel_name) */
                } else {
                    (void)start_refused(SDP_START_PLAY, UI_SCREEN_FILE, s_ui.playback);
                }
            }

            /* A REC or PLAY start the card cannot take (Jack's newest
             * status, sd_popup.c): nothing is sent, and the UI stays on the
             * screen the input was made on, transport as s_prev has it
             * (idle after the PLAY_STOP above), with the pop-up over it. A
             * start changes only the screen and the transport. */
            if (start_refused(sdp_start_of(&s_prev, &s_ui), screen_before, s_prev.playback)) {
                s_prev = s_ui;
                continue;
            }
            emit_commands(&s_prev, &s_ui, ev[i]);
            s_prev = s_ui;
        }

        /* Debug screen: leaving the Speaker page (a turn, BACK) stops its
         * test pattern. */
        TonyDebug_Update(&s_ui, &s_sto);
        window_service();               /* the file-list window the screen needs, one request at a time */
        fx_na_update();                 /* "n/a": the original plays although an effect is selected */
        /* Debug screen, Storage page: Jack is asked for his full status once
         * a second (drain_queues() takes the reply's bus width, capacity and
         * last error into s_sto). Only while storageReqQueue is empty, i.e.
         * Jack has answered every earlier request: when he is busy for
         * seconds (mounting a large card, SDIO timeouts) the requests must
         * not pile up in the 4-deep queue in front of a file-list request,
         * and at most one STATUS reply is ever on its way into the 2-slot
         * reply queue. */
        if (s_ui.screen == UI_SCREEN_DEBUG && s_ui.debug_page == DEBUG_PAGE_STORAGE &&
            (int32_t)(osKernelGetTickCount() - s_sto_req_next_ms) >= 0 &&
            osMessageQueueGetCount(storageReqQueue) == 0U) {
            s_sto_req_next_ms = osKernelGetTickCount() + DEBUG_STATUS_PERIOD_MS;
            request_storage_status();
        }

        render();
        /* After a dismissal this render was the full redraw of the screen
         * underneath (~0.2-0.3 s, no scan): the guard window starts only
         * now, or it would be over before the first scan could use it. */
        if (fault_closed || saver_woke) input_guard_start();
        osDelay(UI_POLL_DELAY_MS);
    }
}
